prompt --application/shared_components/logic/application_processes/redirect_to_requests
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(133736112469231549)
,p_process_sequence=>4
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Redirect to requests'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_home_page  NUMBER := 32;',
'    l_page_alias VARCHAR2(255);',
'BEGIN',
'    BEGIN',
'        SELECT LOWER(page_alias)',
'          INTO l_page_alias',
'          FROM apex_application_pages',
'         WHERE application_id = v(''APP_ID'')',
'           AND page_id        = l_home_page;',
'    EXCEPTION',
'      WHEN OTHERS THEN',
'        l_page_alias := l_home_page;',
'    END;',
'    ',
'    htp.init;',
'    apex_util.redirect_url (p_url => l_page_alias||''?session=''||''&APP_SESSION.'');',
'    apex_application.stop_apex_engine;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when_type=>'NEVER'
,p_version_scn=>1
);
end;
