 p_id=>wwv_flow_imp.id(148360658141992581)
,p_name=>'Custom Authentication'
,p_scheme_type=>'NATIVE_CUSTOM'
,p_attribute_01=>'CHECK_PRIVILEGE'
,p_attribute_03=>'APP_USER_SECURITY.VALID_USER'
,p_attribute_05=>'N'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'FUNCTION CHECK_PRIVILEGE',
'RETURN BOOLEAN',
'AS',
'BEGIN',
'    IF APP_USER_SECURITY.APP_VALIDATE_PRIVILEGE(apex_application.get_application_id, apex_application.get_page_id, apex_application.g_user) = true THEN',
'        RETURN true;',
'    ELSE',
'        RETURN false;',
'    END IF;',
'END;'))
,p_invalid_session_type=>'LOGIN'
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
,p_version_scn=>41756817445366
);
end;
