prompt --application/shared_components/plugins/region_type/com_anychart_apex_anychart
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(1943021956299483322)
,p_plugin_type=>'REGION TYPE'
,p_name=>'COM.ANYCHART.APEX.ANYCHART'
,p_display_name=>'AnyChart for APEX'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('REGION TYPE','COM.ANYCHART.APEX.ANYCHART'),'')
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'FUNCTION render_anychart(',
'    p_region in apex_plugin.t_region',
'  , p_plugin in apex_plugin.t_plugin',
'  , p_is_printer_friendly in boolean',
') return apex_plugin.t_region_render_result AS',
'',
'  V_RETURN apex_plugin.t_region_render_result;',
'  V_SOURCE_TYPE apex_application_page_regions.attribute_01%type := p_region.attribute_01;',
'  V_SOURCE_SQL apex_application_page_regions.attribute_02%type := p_region.attribute_02;',
'  V_SOURCE_JSON apex_application_page_regions.attribute_03%type := p_region.attribute_03;',
'  V_CHART_OPTIONS apex_application_page_regions.attribute_04%type := p_region.attribute_04;',
'  V_HEIGHT apex_application_page_regions.attribute_05%type := p_region.attribute_05;',
'  V_WIDTH apex_application_page_regions.attribute_06%type := p_region.attribute_06;',
'  V_SOURCE_PLSQL apex_application_page_regions.attribute_07%type := p_region.attribute_07;',
'',
'  V_LIC_KEY apex_appl_plugins.attribute_01%type := p_plugin.attribute_01;',
'  V_LIC_KEY_JS VARCHAR2(1000);',
'',
'  V_REGION_ID VARCHAR2(100) := ''acplg_''||p_region.id;',
'',
'  V_HTML CLOB := ''',
'$(document).ready(function(){''||CASE WHEN V_LIC_KEY IS NOT NULL THEN ''anychart.licenseKey("''||V_LIC_KEY||''");'' END||''',
'  anychart.onDocumentReady(function() {',
'    var chart;',
'    var data = #SRC_DATA#;',
'    #CHART_OPTIONS#',
'    chart.container("#REGION_ID#");',
'    chart.draw();',
'  });',
'});'';',
'',
'  l_data_type_list    wwv_flow_global.vc_arr2;',
'  l_column_value_list apex_plugin_util.t_column_value_list;',
'  V_RESULT VARCHAR2(32767);',
'',
'BEGIN',
'  apex_javascript.add_library(p_name => ''anychart.min'', p_directory => p_plugin.file_prefix, p_version=> NULL);',
'  apex_javascript.add_library(p_name => ''anychart-ui.min'', p_directory => p_plugin.file_prefix, p_version=> NULL);',
'  apex_css.add_file(p_name => ''anychart-ui.min'', p_directory => p_plugin.file_prefix);',
'',
'  sys.htp.p(''<div id="''||V_REGION_ID||''"></div>'');',
'',
'  IF V_SOURCE_TYPE = ''SQL'' THEN',
'    V_SOURCE_SQL := V_SOURCE_SQL;',
'  ELSIF V_SOURCE_TYPE = ''PLSQL'' THEN',
'    V_SOURCE_SQL := apex_plugin_util.get_plsql_function_result(p_plsql_function => V_SOURCE_PLSQL);',
'  ELSIF V_SOURCE_TYPE = ''JSON'' THEN',
'    V_RESULT := apex_plugin_util.replace_substitutions(V_SOURCE_JSON);',
'  END IF;',
'',
'  IF V_SOURCE_TYPE IN(''SQL'',''PLSQL'') THEN',
'    FOR I IN 1..100 LOOP',
'      l_data_type_list(I) := apex_plugin_util.c_data_type_varchar2;',
'    END LOOP;',
'',
'    l_column_value_list :=',
'          apex_plugin_util.get_data(',
'              p_sql_statement    => V_SOURCE_SQL,',
'              p_min_columns      => 1,',
'              p_max_columns      => 100,',
'              p_component_name   => NULL,',
'              p_search_type      => NULL,',
'              p_search_column_no => NULL,',
'              p_search_string    => NULL);',
'  ',
'    V_RESULT := ''['';',
'    for i in 1 .. l_column_value_list(1).count loop',
'',
'      IF I = 1 THEN',
'        V_RESULT := V_RESULT||''["''||l_column_value_list(1)(i)||''"'';',
'      ELSE',
'        V_RESULT := V_RESULT||'',["''||l_column_value_list(1)(i)||''"'';',
'      END IF;',
'',
'      FOR J IN 2..l_column_value_list.COUNT LOOP',
'        V_RESULT := V_RESULT||'',"''||l_column_value_list(J)(i)||''"'';',
'      END LOOP;',
'',
'      V_RESULT := V_RESULT || '']'';',
'',
'    end loop;',
'    V_RESULT := V_RESULT || '']'';',
'  END IF;',
'',
'  V_HTML := REPLACE(V_HTML,''#SRC_DATA#'',V_RESULT);',
'  V_HTML := REPLACE(V_HTML,''#REGION_ID#'',V_REGION_ID);',
'  V_HTML := REPLACE(V_HTML,''#CHART_OPTIONS#'',V_CHART_OPTIONS);',
'',
'  apex_css.add(p_css => ''#''||V_REGION_ID||''{height: ''||V_HEIGHT||'';width: ''||V_WIDTH||'';}'');',
'',
'  apex_javascript.add_onload_code(v_html);',
'',
'  /*sys.htp.p(''<script type="text/javascript">'');',
'  sys.htp.p(V_HTML);',
'  sys.htp.p(''</script>'');*/',
'',
'  RETURN V_RETURN;',
'exception',
'  when others then',
'    sys.htp.p(''Error while rendering plugin.'');',
'    sys.htp.p(''Error: ''||sqlerrm);',
'    RETURN V_RETURN;',
'END render_anychart;'))
,p_api_version=>1
,p_render_function=>'render_anychart'
,p_substitute_attributes=>true
,p_version_scn=>41756817476104
,p_subscribe_plugin_settings=>true
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'	AnyChart is the leading JS Charting solution available on the market today. &nbsp;Our JS Charting Engine is designed to work natively within Apex. &nbsp;Our plugin allows you to &nbsp;access all our Charts, Maps, Gantts, and Stock Charts on either a'
||' Trial Basis or with a purchase of the appropriate License.</p>',
''))
,p_version_identifier=>'1.0.1'
,p_about_url=>'http://www.anychart.com/products/oracleapex/'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1400308618700610334)
