'       CASE IS_SEEN',
'        WHEN 1 THEN',
'            ''<span aria-hidden="true" class="t-Icon fa fa-envelope-open-o"></span>''',
'        ELSE',
'            ''<span aria-hidden="true" class="t-Icon fa fa-envelope-o"></span>''',
'        END AS ATTRIBUTE_1,',
'        ''<span aria-hidden="true" class="t-Icon fa fa-envelope-x"></span>'' AS ALERT_ACTION, --ATTRIBUTE_2,',
'       NULL AS ATTRIBUTE_3,',
'       NULL AS ATTRIBUTE_4,',
'       NULL AS ACTIONS',
'  FROM SELLER_NOTIFICATIONS',
' WHERE NVL(IS_CANCELED, 0) = 0',
'   AND ID = :P0_ID;'))
