,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('SELECT COUNT(1) || DECODE(nvl(:P_LANG, ''ar''), ''en'', '' Auction '', '' \0645\0632\0627\062F '') AS COUNT,'),
'       ''alarm-clock'' AS ICON,',
'       1 AS SEQ,',
'       ''auctions'' AS TYPE,',
unistr('       ''\0627\0644\0645\0632\0627\062F\0627\062A'' AS TITLE'),
'  FROM AUCTIONS',
' WHERE SELLER_ID = :P_SELLER_ID',
'UNION ALL',
unistr('SELECT COUNT(1) || DECODE(nvl(:P_LANG, ''ar''), ''en'', '' Product '', '' \0645\0646\062A\062C '') AS COUNT,'),
'       ''package'' AS ICON,',
'       2 AS SEQ,',
'       ''products'' AS TYPE,',
unistr('       ''\0627\0644\0645\0646\062A\062C\0627\062A'' AS TITLE'),
'  FROM PRODUCTS',
' WHERE SELLER_ID = :P_SELLER_ID',
'UNION ALL',
unistr('SELECT COUNT(1) || DECODE(nvl(:P_LANG, ''ar''), ''en'', '' Active Auction '', '' \0645\0632\0627\062F \0642\0627\0626\0645 '') AS COUNT,'),
'       ''clock-o'' AS ICON,',
'       3 AS SEQ,',
'       ''current_auctions'' AS TYPE,',
unistr('       ''\0627\0644\0645\0632\0627\062F\0627\062A \0627\0644\0642\0627\0626\0645\0629'' AS TITLE'),
'  FROM AUCTIONS',
' WHERE START_DATE > SYSDATE',
'   AND END_DATE IS NULL',
'   AND SELLER_ID = :P_SELLER_ID',
'UNION ALL',
unistr('SELECT COUNT(1) || DECODE(nvl(:P_LANG, ''ar''), ''en'', '' Ended Auction '', '' \0645\0632\0627\062F \0645\0646\062A\0647\064A '') AS COUNT,'),
'       ''check-circle-o'' AS ICON,',
'       4 AS SEQ,',
'       ''ended_auctions'' AS TYPE,',
unistr('       ''\0627\0644\0645\0632\0627\062F\0627\062A \0627\0644\0645\0646\062A\0647\064A\0629'' AS TITLE'),
'  FROM AUCTIONS',
' WHERE IS_ENDED = 1',
'   AND SELLER_ID = :P_SELLER_ID',
' ORDER BY SEQ;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
