 p_id=>wwv_flow_imp.id(132874558080779122)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Redirect to Requests Page'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_home_page  NUMBER := 32;',
'    l_page_alias VARCHAR2(255);',
'BEGIN',
'    BEGIN',
'        SELECT LOWER(page_alias)',
'          INTO l_page_alias',
'          FROM apex_application_pages',
'         WHERE application_id = v(''APP_ID'')',
'           AND page_id        = l_home_page;',
'    EXCEPTION',
'      WHEN OTHERS THEN',
'        l_page_alias := l_home_page;',
'    END;',
'    ',
'    htp.init;',
'    APEX_UTIL.redirect_url ( p_url => l_page_alias || ''?session='' || ''&APP_SESSION.'' );',
'    apex_application.stop_apex_engine;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT 1',
'  FROM EMPLOYEES',
' WHERE USER_ID   = :P_USER_ID',
'   AND SELLER_ID = :P_SELLER_ID',
'   AND NVL(IS_ACTIVE, 0) = 0;'))
,p_process_when_type=>'EXISTS'
,p_internal_uid=>37848839447269530
);
end;
