,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create Collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF NOT APEX_COLLECTION.collection_exists(''AUCTION_DETAILS'') THEN',
'        APEX_COLLECTION.create_collection(''AUCTION_DETAILS'');',
'        APEX_COLLECTION.add_member (',
'            p_collection_name => ''AUCTION_DETAILS'',',
'            p_c001 => :P2_CATEGORY_ID, ',
'            p_c002 => :P2_DEPENDENT,',
'            p_c003 => :P2_TRSYAH,',
'            p_c004 => :P2_INSURANCE_DEDUCTED,',
'            p_c005 => :P2_IS_SADAD,',
'            p_c006 => :P2_IS_SANAD,',
'            p_c007 => :P2_COMMISSION_TYPE_ID,',
'            p_c008 => :P2_COMMISSION,',
'            p_c009 => :P2_PAYMENT_DEADLINE,',
'            p_c010 => :P2_NAME_AR,',
'            p_c011 => :P2_LOGO_URL,',
'            p_c012 => :P2_BROCHURE_URL,',
'            p_c013 => :P2_VIDEO_URL,',
'            p_c014 => :P2_TERMS_AR',
'        );',
'    ELSE',
'        APEX_COLLECTION.add_member (',
'            p_collection_name => ''AUCTION_DETAILS'',',
'            p_c001 => :P2_CATEGORY_ID, ',
'            p_c002 => :P2_DEPENDENT,',
'            p_c003 => :P2_TRSYAH,',
'            p_c004 => :P2_INSURANCE_DEDUCTED,',
'            p_c005 => :P2_IS_SADAD,',
'            p_c006 => :P2_IS_SANAD,',
