,p_event_result=>'TRUE'
,p_action_sequence=>40
,p_execute_on_page_init=>'N'
,p_name=>'Create Request to admin'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count             NUMBER;',
'    v_name              VARCHAR2(255);',
'    v_image_url         VARCHAR2(1000);',
'    v_auctions_count    VARCHAR2(1000);',
'    v_product_ids       VARCHAR2(255);',
'    l_result            CLOB;',
'    l_message           VARCHAR2(32700);',
'BEGIN',
'    SELECT jt.name, jt.imageUrl, jt.auctionsCount',
'      INTO v_name, v_image_url, v_auctions_count',
'      FROM',
'      JSON_TABLE (:P3_JSON,',
'         ''$.auctionContainers[*]''',
'            COLUMNS (',
'                id              varchar2(500)  path ''$._id'',',
'                name            varchar2(500)  path ''$.name'',',
'                imageUrl        varchar2(1000) path ''$.imageUrl'',',
'                auctionsCount   varchar2(1000) path ''$.auctionsCount''',
'            )',
'        ) AS jt',
'       WHERE jt.id = :P3_AUCTION_ID;',
'    ',
'    l_result := SYSTEM_INTEGRATION.auction_container_details (',
'                    p_auction_id    => :P3_AUCTION_ID,',
'                    p_seller_id     => :P_SELLER_ID,',
'                    p_message       => l_message',
'                );',
'',
'    IF l_result <> ''1'' THEN',
'        RAISE_APPLICATION_ERROR (-20007, l_message);',
'    END IF;',
'',
'    SELECT LISTAGG(jt.product, '','')',
'      INTO v_product_ids',
'      FROM',
'      JSON_TABLE (l_message,',
'         ''$.auctions[*]''',
'            COLUMNS (',
'                product varchar2(500) path ''$.product''',
'            )',
'      ) AS jt;',
'',
'    SELECT count(1)',
'      INTO v_count',
'      FROM AUCTION_DELETE_REQUESTS',
'     WHERE AUCTION_ID = :P3_AUCTION_ID;',
'',
'    IF v_count = 0 THEN',
'        INSERT INTO AUCTION_DELETE_REQUESTS (',
'            SELLER_ID, USER_ID, AUCTION_ID, PRODUCT_IDS, AUCTION_NAME, IMAGE_URL, BIDS, PARTICIPANTS, AUCTIONS_COUNT, STATUS, TYPE',
'        ) VALUES (',
'            :P_SELLER_ID, :P_USER_ID, :P3_AUCTION_ID, v_product_ids, v_name, v_image_url, 25, 7, v_auctions_count,',
'            LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''pending'', p_lookup_code => ''request_status''),',
'            LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''container'', p_lookup_code => ''auction_delete_type'')',
'        );',
'    END IF;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20007, ''Insertion Error'');',
'    END IF;',
'',
unistr('    apex_application.g_print_success_message := ''\062A\0645 \062A\0642\062F\064A\0645 \0637\0644\0628 \0627\0644\062D\0630\0641 \0628\0646\062C\0627\062D'';'),
'END;'))
,p_attribute_02=>'P3_AUCTION_ID,P3_JSON'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(67100252467960332)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Get Auctions'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_result    CLOB;',
'    l_message   VARCHAR2(32700);',
'BEGIN',
'    l_result := SYSTEM_INTEGRATION.auction_containers (',
'                    p_seller_id     => :P_SELLER_ID,',
'                    p_message       => l_message',
'                );',
'',
'    IF l_result <> ''1'' THEN',
'        RAISE_APPLICATION_ERROR (-20007, l_message);',
'    END IF;',
'    ',
'    :P3_JSON := l_message;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>51067107788025227
);
