'       VIDEO_URL,',
'       BROCHURE_URL,',
unistr('       ''1 - \0627\0644\062A\0633\062C\064A\0644 \0641\064A \0645\0646\0635\0629 \0645\0628\0627\0634\0631 \0644\0644\0645\0632\0627\062F\0627\062A 2 - \0633\062F\0627\062F \0645\0628\0644\063A \0627\0644\0645\0634\0627\0631\0643\0629 \062D\0633\0628 \0627\0644\0639\0631\0627\0628\064A\0646 \0639\0646 \0637\0631\064A\0642 \0645\0646\0635\0629 \0645\0628\0627\0634\0631 \0644\0644\0645\0632\0627\062F\0627\062A \0648\064A\0639\062A\0628\0631 \0627\0644\0645\0628\0644\063A \062C\0632\0621\0627 \0645\0646 \0627\0644\062B\0645\0646 \0644\0645\0646 \064A\0631\0633\0648\0627 \0639\0644\064A\0647 \0627\0644\0645\0632\0627\062F \0648\0644\0627 \064A\062D\0642 \0644\0647 \0627\0633\062A\0631\062F\0627\062F\0647. \0648\0641\064A \062D\0627\0644 \0631\0633\0648 \0627\0644\0645\0632\0627\062F \064A\062D\0631\0631 \0634\064A\0643 \0628\0628\0627\0642\064A \0642\064A\0645\0629 \0627\0644\0639\0642\0627\0631 \0628\0627\0633\0645 \0645\0631\0643\0632 \0627\0644\0627\0633\0646\0627\062F \0648\0627\0644\062A\0635\0641\064A\0629')
||unistr(' \0627\0646\0641\0627\0630 3 - \0639\0646\062F \0631\0633\0648 \0627\0644\0645\0632\0627\062F \0639\0644\0649 \0627\0644\0645\0634\062A\0631\064A \064A\062A\0645 \0633\062F\0627\062F \0627\0644\0645\0628\0644\063A \0641\0648\0631\0627. \0648\0641\064A \062D\0627\0644 \062A\0639\0630\0631 \0627\0644\0633\062F\0627\062F \062E\0644\0627\0644 10 \0627\064A\0627\0645 \0639\0645\0644 \064A\0639\0627\062F \0627\0644\0645\0632\0627\062F \0639\0644\0649 \062D\0633\0627\0628 \0627\0644\0645\0634\062A\0631\064A \0648\064A\062A\062D\0645\0644 \062C\0645\064A\0639 \0645\0627 \0646\0642\0635 \0645\0646 \0627\0644\0645\0628\0644\063A \0648\062C\0645\064A\0639 \062A\0643\0627\0644\064A\0641 \0627\0644\0645\0632\0627\062F'' AS TERMS_AR'),
