wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(63096593369000407)
,p_name=>'Card details pass'
,p_template=>wwv_flow_imp.id(148155955406951451)
,p_display_sequence=>60
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noBorder:t-Region--hiddenOverflow:margin-top-md'
,p_component_template_options=>'#DEFAULT#'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ''T-'' || t.ID AS CODE,',
'',
'        ------all pages',
unistr('        DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0627\0644\062D\0627\0644\0629: '',''Status: '' ) AS STATUS_STATIC,'),
unistr('        DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0627\0644\062A\0635\0646\064A\0641: '',''Category:'' ) AS CATEGORY_STATIC,'),
unistr('        DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0627\0644\0645\0634\0627\0631\0643\064A\0646"'',''Participants: '' ) AS PARTICIPANTS_STATIC,'),
unistr('        DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0627\0644\0645\0632\0627\064A\062F\0627\062A:'',''Bids: '' ) AS BIDS_STATIC,'),
unistr('        DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0627\0644\0632\0627\064A\062F\0627\062A \0627\0644\0623\0644\064A\0629:'',''Auto Bids: '' ) AS AUTO_BIDS_STATIC,'),
unistr('        DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0633\0639\0631 \0627\0644\0625\0641\062A\062A\0627\062D: '',''Opening Price:'' ) AS START_PRICE_STATIC,'),
unistr('        DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0623\062F\0646\0649 \0633\0639\0631 \0644\0644\0628\064A\0639: '',''Minimum Selling Price:'' ) AS MINIMUM_PRICE_STATIC,'),
unistr('        DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0645\0632\0627\062F \0625\0644\0643\062A\0631\0648\0646\064A (\0632\0645\0646\064A)'',''Onlin Auction (Timed)'' ) AS AUCTION_TYPE_STATIC,'),
'        -- all other pages',
unistr('        DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0627\0644\0643\0648\062F: '',''Code:'' ) AS CODE_STATIC,'),
unistr('        DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0628\062F\0623 \0641\064A: '',''Started At:'' ) AS SATRT_DATE_STATIC,'),
unistr('        DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\064A\0646\062A\0647\064A \0641\064A: '',''Ends At:'' ) AS END_DATE_STATIC,'),
unistr('        DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0645\062F\0629 \0627\0644\0645\0632\0627\062F : '',''Auction Duration: '' ) AS AUCTION_DURATION_STATIC,'),
unistr('        DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0627\0644\0645\0647\062A\0645\064A\0646: '',''Interested: '' ) AS INTERESTED_STATIC,      '),
'        --PASS',
unistr('        DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0627\0639\0644\0649 \0639\0631\0636: '',''Highest Bid: '' ) AS HIGHEST_BID_STATIC,'),
unistr('        DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\062D\0627\0644\0629 \0627\0644\0645\0632\0627\062F:'',''AUCTUON STATUS:'' ) AS AUCTION_STATUS_STATIC,'),
'        NULL AS CARD_LINK,',
'        0 AS PARTICIPANTS,',
'        0 AS BIDS,',
'        0 AS AUTO_BIDS,',
'        0 AS INTERESTED,        ',
'        0 AS HIGHEST_PRICE, --PASS',
'        p.NAME_AR AS NAME,',
'        t.START_DATE AS START_DATE,',
'        t.END_DATE AS END_DATE,',
'        ROUND(t.END_DATE - t.START_DATE) + 1 AS DURATION_DATE,',
'        t.ALLOW_SELL_PRICE AS MINIMUM_PRICE ,',
'        t.START_PRICE AS START_PRICE ,',
'        p.MAIN_IMAGE_URL AS MAIN_IMAGE,',
'        (SELECT g.NAME_AR FROM CATEGORIES g WHERE g.ID = p.CATEGORY_ID ) AS CATEGORY,',
'        LOOKUPS_MNT.lookup_detail_name_by_id (p_lookup_detail_id => p.STATUS, p_lang => ''ar'') AS STATUS,',
'        (SELECT COUNT(1) FROM BUYER_TIMED_AUCTION_WATCHES WHERE TIMED_AUCTION_ID = t.ID) AS WATCHERS,',
'        (SELECT COUNT(1) FROM BUYER_VISITED_AUCTION_CONTAINERS WHERE AUCTION_CONTAINER_ID = t.AUCTION_CONTAINER_ID) AS VISITORS',
'  FROM  PRODUCTS p,',
'        PRODUCT_IN_TIMED_AUCTION t',
' WHERE  p.ID = t.PRODUCT_ID',
'   AND  t.SELLER_ID = :P_SELLER_ID',
'   AND  LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => t.STATUS) = ''pass''',
''))
