wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(151347086007392458)
,p_plug_name=>'CARDS'
,p_region_css_classes=>'refresh'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(148092133649951414)
,p_plug_display_sequence=>20
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_table  VARCHAR2(255);',
'BEGIN',
'    IF LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P6_AUCTION_TYPE_ID) = ''timed'' THEN',
'        return ''',
unistr('            SELECT ''''\0645\0641\0639\0644\0629'''' AS LABEL,'),
'                   COUNT(1) AS COUNT,',
'                   ''''live_now'''' AS TYPE',
'              FROM PRODUCT_IN_TIMED_AUCTION',
'             WHERE STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''''live_now'''', p_lookup_code => ''''timed_auction_status'''')',
'               AND SELLER_ID = :P_SELLER_ID',
'            UNION ALL',
unistr('            SELECT ''''\0639\0644\0649 \0639\0631\0636'''' AS LABEL,'),
'                   COUNT(1) AS COUNT,',
'                   ''''offer'''' AS TYPE',
'              FROM PRODUCT_IN_TIMED_AUCTION',
'             WHERE STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''''offer'''', p_lookup_code => ''''timed_auction_status'''')',
'               AND SELLER_ID = :P_SELLER_ID',
'            UNION ALL',
unistr('            SELECT ''''\0645\0628\0627\0639\0629'''' AS LABEL,'),
'                   COUNT(1) AS COUNT,',
'                   ''''sold'''' AS TYPE',
'              FROM PRODUCT_IN_TIMED_AUCTION',
'             WHERE STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''''sold'''', p_lookup_code => ''''timed_auction_status'''')',
'               AND SELLER_ID = :P_SELLER_ID',
'            UNION ALL',
unistr('            SELECT ''''\0644\0645 \062A\0628\0627\0639'''' AS LABEL,'),
'                   COUNT(1) AS COUNT,',
'                   ''''pass'''' AS TYPE',
'              FROM PRODUCT_IN_TIMED_AUCTION',
'             WHERE STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''''pass'''', p_lookup_code => ''''timed_auction_status'''')',
'               AND SELLER_ID = :P_SELLER_ID',
'        '';',
'    ELSIF LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P6_AUCTION_TYPE_ID) = ''timed_live'' THEN',
'        return ''',
unistr('            SELECT ''''\0645\0641\0639\0644\0629'''' AS LABEL,'),
'                   COUNT(1) AS COUNT,',
'                   ''''live_now'''' AS TYPE',
'              FROM PRODUCT_IN_LIVE_AUCTION',
'             WHERE STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''''live_now'''', p_lookup_code => ''''timed_auction_status'''')',
'               AND LIVE_AUCTION_ID IN (SELECT ID FROM LIVE_AUCTION WHERE SELLER_ID = :P_SELLER_ID)',
'            UNION ALL',
unistr('            SELECT ''''\0639\0644\0649 \0639\0631\0636'''' AS LABEL,'),
'                   COUNT(1) AS COUNT,',
'                   ''''offer'''' AS TYPE',
'              FROM PRODUCT_IN_LIVE_AUCTION',
'             WHERE STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''''offer'''', p_lookup_code => ''''timed_auction_status'''')',
'               AND LIVE_AUCTION_ID IN (SELECT ID FROM LIVE_AUCTION WHERE SELLER_ID = :P_SELLER_ID)',
'            UNION ALL',
unistr('            SELECT ''''\0645\0628\0627\0639\0629'''' AS LABEL,'),
'                   COUNT(1) AS COUNT,',
'                   ''''sold'''' AS TYPE',
'              FROM PRODUCT_IN_LIVE_AUCTION',
'             WHERE STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''''sold'''', p_lookup_code => ''''timed_auction_status'''')',
'               AND LIVE_AUCTION_ID IN (SELECT ID FROM LIVE_AUCTION WHERE SELLER_ID = :P_SELLER_ID)',
'            UNION ALL',
unistr('            SELECT ''''\0644\0645 \062A\0628\0627\0639'''' AS LABEL,'),
'                   COUNT(1) AS COUNT,',
'                   ''''pass'''' AS TYPE',
'              FROM PRODUCT_IN_LIVE_AUCTION',
'             WHERE STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''''pass'''', p_lookup_code => ''''timed_auction_status'''')',
'               AND LIVE_AUCTION_ID IN (SELECT ID FROM LIVE_AUCTION WHERE SELLER_ID = :P_SELLER_ID)',
'        '';',
'    ELSE',
'        return ''',
unistr('            SELECT ''''\0645\0641\0639\0644\0629'''' AS LABEL,'),
'                   0 AS COUNT,',
'                   '''''''' AS TYPE',
'              FROM DUAL',
'            UNION ALL',
unistr('            SELECT ''''\0639\0644\0649 \0639\0631\0636'''' AS LABEL,'),
'                   0 AS COUNT,',
'                   '''''''' AS TYPE',
'              FROM DUAL',
'            UNION ALL',
unistr('            SELECT ''''\0645\0628\0627\0639\0629'''' AS LABEL,'),
'                   0 AS COUNT,',
'                   '''''''' AS TYPE',
'              FROM DUAL',
'            UNION ALL',
unistr('            SELECT ''''\0644\0645 \062A\0628\0627\0639'''' AS LABEL,'),
'                   0 AS COUNT,',
'                   '''''''' AS TYPE',
'              FROM DUAL',
'        '';',
'    END IF;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P6_AUCTION_TYPE_ID'
,p_plug_query_num_rows_type=>'SCROLL'
,p_plug_column_width=>'#TYPE#'
,p_show_total_row_count=>false
);
