'       ''<img src="''|| LOGO_URL ||''" alt="Auction Logo" class="auction-image" style="width:30px;height:30px;" />'' AS LOGO_URL,',
'       DECODE(:P_LANG, ''ar'', NAME_AR, NAME_EN) AS NAME,',
'       AUCTION_TYPE_ID,',
'       AUCTION_TYPE_ID AS TYPE_ID,',
'       START_DATE,',
'       END_DATE,',
'       TRUNC(END_DATE - START_DATE) + 1 AS DURATION,',
