,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count  NUMBER;',
'BEGIN',
'    SELECT COUNT(1)',
'      INTO v_count',
'      FROM REAL_STATE_DETAILS r,',
'           PRODUCTS p',
'     WHERE r.PRODUCT_ID = p.ID',
'       AND TRIM(r.INSTRUMENT_NO) = TRIM(:P10_INSTRUMENT_NO)',
'       AND p.SELLER_ID= :P10_SELLER_ID;',
'    ',
'    IF v_count > 0 THEN',
unistr('        RAISE_APPLICATION_ERROR(-20001, ''\0631\0642\0645 \0627\0644\0635\0643 \0645\0648\062C\0648\062F \0628\0627\0644\0641\0639\0644'');'),
