 p_id=>wwv_flow_imp.id(61569253215220329)
,p_process_sequence=>90
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'upload products imgs'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_name         VARCHAR2(255);',
'    l_request_url	    VARCHAR2(32767);',
'    l_result	        CLOB;',
'BEGIN',
'    FOR i IN (SELECT c001 AS FILE_NAME, c002 AS MIME_TYPE, blob001 AS BLOB_CONTENT FROM apex_collections WHERE collection_name = ''DROPZONE_UPLOAD'') LOOP',
'        l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                            || DBMS_RANDOM.STRING(''x'', 8)',
'                            || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => i.MIME_TYPE);',
'',
'        l_request_url := :G_OCI_BASE_URL||''/b/sellers/o/''||l_file_name;',
'',
'        l_result := APEX_WEB_SERVICE.make_rest_request (',
'                        p_url                  => l_request_url,',
'                        p_http_method          => ''PUT'',',
'                        p_body_blob            => i.BLOB_CONTENT,',
'                        p_credential_static_id => ''OCI_AUTH''',
'                    );',
'',
'        IF APEX_WEB_SERVICE.g_status_code NOT IN ( 200, 201, 202, 203, 204, 205, 206, 207, 226 ) THEN',
'            SYSTEM_CONTROLS.ERROR_LOGS ( p_error_type    => ''SYSTEM_ERROR'',',
'                                         p_process_name  => ''OCI_OS.put_object_P3 - App: '' || :APP_ID,',
'                                         p_error_code    => -2,',
'                                         p_error_message => SUBSTR(l_result, 1, 4000),',
'                                         p_logger_name   => :APP_USER',
'                                    );',
'            RAISE_APPLICATION_ERROR(-20001, ''Error with uploading Data!'');',
'        END IF;',
'',
'        INSERT INTO PRODUCT_IMAGES ( PRODUCT_ID, URL, FILE_NAME, MIME_TYPE, IS_ACTIVE )',
'                VALUES ( :P10_ID, l_request_url, i.FILE_NAME, i.MIME_TYPE, 1 );',
'        ',
'        IF SQL%ROWCOUNT = 0 THEN',
unistr('            RAISE_APPLICATION_ERROR(-20002, ''\062E\0637\0623 \0641\064A \0631\0641\0639 \0627\0644\0635\0648\0631!'');'),
'        END IF;',
'    END LOOP;',
'    ',
'    APEX_COLLECTION.TRUNCATE_COLLECTION (p_collection_name => ''DROPZONE_UPLOAD'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SELECT 1 FROM apex_collections WHERE collection_name = ''DROPZONE_UPLOAD'''
,p_process_when_type=>'EXISTS'
,p_internal_uid=>45536108535285224
);
