,p_chart_id=>wwv_flow_imp.id(32740110772509707)
,p_seq=>10
,p_name=>'Bidders'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DECODE(NVL(:P_LANG, ''ar''), ''ar'', a.NAME_AR, a.NAME_EN) AS NAME, p.AUCTION_CONTAINER_ID, COUNT(p.last_bid) AS BIDS',
'  FROM PRODUCT_IN_TIMED_AUCTION p,',
'       AUCTIONS a',
' WHERE a.ID = p.AUCTION_CONTAINER_ID',
'       AND p.SELLER_ID =  :P_SELLER_ID',
' GROUP BY p.AUCTION_CONTAINER_ID, a.NAME_AR, a.NAME_EN'))
,p_items_value_column_name=>'BIDS'
,p_items_label_column_name=>'NAME'
,p_assigned_to_y2=>'off'
,p_items_label_rendered=>false
,p_items_label_display_as=>'PERCENT'
,p_threshold_display=>'onIndicator'
);
