wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(63108572554151937)
,p_plug_name=>'Product Status'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(148092133649951414)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT COUNT(ID) AS COUNT,',
'        LOOKUPS_MNT.lookup_detail_name_by_id (  ',
'            p_lookup_detail_id  => STATUS,  ',
'            p_lang              => :P_LANG',
'        ) AS PRODUCT_STATUS,',
'        STATUS AS  STATUS_ID',
'   FROM PRODUCTS',
'  WHERE SELLER_ID = :P_SELLER_ID',
'        AND IS_ACTIVE = 1 ',
'        AND IS_DELETED = 0',
'        AND STATUS IN(LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''available'',p_lookup_code  => ''product_status''),',
'                              LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''on_auction'',p_lookup_code  => ''product_status''), ',
'                              LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''sold'',p_lookup_code  => ''product_status''))',
'  GROUP BY STATUS;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P15_STATUS_ID'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
);
