'SELECT ID,',
'       BUYER_ID,',
'       CITY_ID,',
'       CATEGORY_ID,',
'       SUB_CATEGORY_ID,',
'       SELLER_ID,',
'       STOCK_NO,',
'       IN_AUCTION_COUNT,',
'       DECODE(:P_LANG, ''ar'', NAME_AR, NAME_EN) AS NAME,',
'       DECODE(:P_LANG, ''ar'', DESCRIPTION_AR, DESCRIPTION_EN) AS DESCRIPTION,',
'       DECODE(:P_LANG, ''ar'', NOTES_AR, NOTES_EN) AS NOTES,',
'       DECODE(:P_LANG, ''ar'', ADDRESS_AR, ADDRESS_EN) AS ADDRESS,',
'       DECODE(:P_LANG, ''ar'', WARRANTY_NOTES_AR, WARRANTY_NOTES_EN) AS WARRANTY_NOTES,',
'       ''<img src="''|| MAIN_IMAGE_URL ||''" alt="Main Image" class="product-image" style="width:25px;height:25px;" />'' AS MAIN_IMAGE,',
'       VIDEO_URL,',
'       CASE',
'        WHEN VIDEO_URL IS NOT NULL THEN',
'            ''<span aria-hidden="true" class="fa fa-play-circle-o"></span>''',
'        ELSE ''''',
'       END AS VIDEO_URL_CLASS,',
'       MAP_URL,',
'       TYPE_ID,',
'       WARRANTY_ID,',
'       STATUS,',
'       IS_ACTIVE,',
'       CREATED_BY,',
'       CREATED_DATE,',
'       MODIFIED_BY,',
'       MODIFIED_DATE,',
'       APEX_ITEM.checkbox2 (p_idx          => 1,',
'                            p_value        => ID,',
'                            p_attributes   => '' class="checkbox"'') AS CHECKBOX',
'  FROM PRODUCTS',
' WHERE SELLER_ID = :P_SELLER_ID',
'        AND IS_ACTIVE = 1 ',
'        AND IS_DELETED = 0',
'   AND (STATUS = :P15_STATUS_ID OR :P15_STATUS_ID IS NULL)',
' ORDER BY ID DESC;'))
