,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(148128308199951436)
,p_plug_display_sequence=>80
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select p.ID,',
'       p.PRODUCT_ID,',
'       p.NAME_AR,',
'       CASE',
'        WHEN p.REPORT_URL IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS REPORT_URL_CLASS,',
'       p.REPORT_URL AS URL',
'  from PRODUCT_REPORTS p,',
'       CAR_DETAILS c,',
'       REAL_STATE_DETAILS r',
' WHERE p.PRODUCT_ID = c.PRODUCT_ID(+)',
'       AND p.PRODUCT_ID = r.PRODUCT_ID(+)',
'       AND p.PRODUCT_ID = :P23_ID',
'UNION ALL',
'    SELECT c.ID,',
'            c.PRODUCT_ID,',
'            ''Document'' AS REPORT_NAME,',
'            CASE',
'            WHEN c.DOCUMENT_URL IS NOT NULL THEN',
'                ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'            ELSE ''''',
'            END AS DOCUMENT_URL_CLASS,',
'            c.DOCUMENT_URL AS URL',
'from CAR_DETAILS c,',
'    REAL_STATE_DETAILS r',
'WHERE c.PRODUCT_ID = r.PRODUCT_ID(+)',
'    AND c.PRODUCT_ID = :P23_ID',
'UNION ALL',
'    SELECT c.ID,',
'            c.PRODUCT_ID,',
'            ''inspection'' AS REPORT_NAME,',
'            CASE',
'            WHEN c.INSPECTION_URL IS NOT NULL THEN',
'                ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'            ELSE ''''',
'            END AS INSPECTION_URL_CLASS,',
'            c.INSPECTION_URL',
'from CAR_DETAILS c,',
'    REAL_STATE_DETAILS r',
'WHERE c.PRODUCT_ID = r.PRODUCT_ID(+)',
'    AND c.PRODUCT_ID = :P23_ID',
''))
