,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_result  NUMBER;',
'    v_message VARCHAR2(255);',
'BEGIN',
'    v_result := PRODUCT.UPDATE_PRODUCTS(',
'                    -- from products table',
'                    P_product_id                           => :P23_ID,',
'                    p_seller_id                            => :P23_SELLER_ID,',
'                    p_type                                 => :P23_TYPE_ID,',
'                    p_name_ar                              => :P23_NAME_AR,',
'                    p_city_id                              => :P23_CITY_ID,',
'                    p_video_url                            => :P23_VIDEO_URL,',
'                    p_category_id                          => :P23_CATEGORY_ID,',
'                    p_subcategory_id                       => :P23_SUB_CATEGORY_ID,',
'                    -- p_other_category                       => :P23_OTHER_CATEGORY,',
'                    p_reference_no                         => :P23_REFERENCE_NO,',
'                    p_desc_ar                              => :P23_DESCRIPTION_AR,',
'                    p_address_ar                           => :P23_ADDRESS_AR,',
'                    p_map_url                              => :P23_MAP_URL,',
'',
'                    -- from real estate details table',
'                    p_instrument_no                        => :P23_INSTRUMENT_NO,',
'                    p_neighbourhoods_id                    => :P23_NEIGHBOURHOODS_ID,',
'                    P_street_name_ar                       => :P23_STREET_NAME_AR,',
'                    p_is_there_mortgage                    => :P23_IS_THERE_MORTGAGE,',
'                    p_is_rights_and_obligations            => :P23_IS_RIGHTS_AND_OBLIGATIONS,',
'                    p_is_information_that_affect_property  => :P23_IS_INFORMATION_THAT_AFFECT_PROPERTY,',
'                    p_there_mortgage_ar                    => :P23_THERE_MORTGAGE_AR,',
'                    p_information_that_affect_property_ar  => :P23_INFORMATION_THAT_AFFECT_PROPERTY_AR,',
'                    p_rights_and_obligations_ar            => :P23_RIGHTS_AND_OBLIGATIONS_AR,',
'                    p_usage_id                             => :P23_USAGE_ID,',
'                    p_facade_id                            => :P23_FACADE_ID,',
'                    p_ad_sub_type_id                       => :P23_AD_SUB_TYPE_ID,',
'                    p_space                                => :P23_SPACE,',
'                    p_street_width                         => :P23_STREET_WIDTH,',
'                    p_construction_date                    => :P23_CONSTRUCTION_DATE,',
'                    p_governorate                          => :P23_GOVERNORATE,',
'',
'                    -- from car details table',
'                    p_make_id                              => :P23_VEHICLE_MAKE_ID,',
'                    p_model_id                             => :P23_VEHICLE_MODEL_ID,',
'                    p_year                                 => :P23_YEAR,',
