wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(59988438092810442)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insert / Udate'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE ',
'    v_count NUMBER;',
'BEGIN',
'    SELECT COUNT(1) INTO v_count FROM AUCTION_TEMP WHERE SELLER_ID = :P_SELLER_ID;',
'    ',
'    IF v_count = 0 THEN',
'',
'        IF :P24_DEPENDENT = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''infath'', p_lookup_code => ''auction_dependency'') THEN ',
'            IF :P24_CATEGORY_ID = :P24_CATEGORY_PREAL_ESTATES_ID THEN',
'                IF:P24_AUCTION_TYPE_ID IS NULL OR :P24_CATEGORY_ID IS NULL OR :P24_DEPENDENT IS NULL OR :P24_PAYMENT_DEADLINE IS NULL OR',
'                  :P24_NAME_AR IS NULL OR :P24_VIDEO_URL IS NULL OR :P24_LOGO IS NULL OR :P24_BROCHURE IS NULL THEN',
'                    RAISE_APPLICATION_ERROR (-20001, ''Missing Data!'');',
'                END IF;',
'                INSERT INTO AUCTION_TEMP(SELLER_ID, AUCTION_TYPE_ID, CATEGORY_ID, PRODUCT_TYPE_ID, INSURANCE_DEDUCTED, TRSYAH, INSURANCE_METHOD,',
'                                                  COMMISSION, COMMISSION_TYPE_ID, PAYMENT_DEADLINE, NAME_AR, LOGO_URL, BROCHURE_URL, VIDEO_URL,',
'                                                  AUCTION_TERMS_AR, IS_WINNING_PRICE_HAS_VAT, SADAD_BILL_TYPE)',
'                     VALUES (:P_SELLER_ID, :P24_AUCTION_TYPE_ID, :P24_CATEGORY_ID, :P24_DEPENDENT, 1, 0, :P24_INSURANCE_METHOD, :P24_COMMISSION, ',
'                             LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''percentage'', p_lookup_code => ''commission_type''),',
'                             :P24_PAYMENT_DEADLINE, :P24_NAME_AR, :P24_LOGO_URL, :P24_BROCHURE_URL, :P24_VIDEO_URL, :P24_TERMS_AR, :P24_IS_WINNING_PRICE_HAS_VAT, :P24_SADAD_BILLING_TYPE)',
'                    RETURNING ID INTO :P24_AUCTION_ID;',
'',
'                IF SQL%Rowcount = 0 THEN',
'                    RAISE_APPLICATION_ERROR (-20002, ''Server error'');',
'                END IF;',
'            END IF;',
'            IF :P24_CATEGORY_ID = :P24_CATEGORY_PORTABLE_ID  THEN',
'                IF:P24_AUCTION_TYPE_ID IS NULL OR :P24_CATEGORY_ID IS NULL OR :P24_DEPENDENT IS NULL OR :P24_TRSYAH IS NULL OR',
'                  :P24_INSURANCE_DEDUCTED IS NULL OR :P24_NAME_AR IS NULL OR :P24_VIDEO_URL IS NULL OR :P24_LOGO IS NULL OR :P24_BROCHURE IS NULL THEN',
'                    RAISE_APPLICATION_ERROR (-20003, ''Missing Data!'');',
'                END IF;',
'',
'                INSERT INTO AUCTION_TEMP(SELLER_ID, AUCTION_TYPE_ID, CATEGORY_ID, PRODUCT_TYPE_ID, INSURANCE_DEDUCTED, TRSYAH, INSURANCE_METHOD,',
'                                                  COMMISSION, COMMISSION_TYPE_ID, PAYMENT_DEADLINE, NAME_AR, LOGO_URL, BROCHURE_URL, VIDEO_URL,',
'                                                  AUCTION_TERMS_AR, SADAD_BILL_TYPE, IS_WINNING_PRICE_HAS_VAT)',
'',
'                     VALUES (:P_SELLER_ID, :P24_AUCTION_TYPE_ID, :P24_CATEGORY_ID, :P24_DEPENDENT, :P24_INSURANCE_DEDUCTED, :P24_TRSYAH,',
'                             :P24_INSURANCE_METHOD, 5,LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''percentage'',',
'                              p_lookup_code => ''commission_type''), :P24_PAYMENT_DEADLINE, :P24_NAME_AR, :P24_LOGO_URL, :P24_BROCHURE_URL,',
'                              :P24_VIDEO_URL, :P24_TERMS_AR, :P24_SADAD_BILLING_TYPE, :P24_IS_WINNING_PRICE_HAS_VAT )',
'                    RETURNING ID INTO :P24_AUCTION_ID;',
'',
'                IF SQL%Rowcount = 0 THEN',
'                    RAISE_APPLICATION_ERROR (-20004, ''Server error'');',
'                END IF;',
'            END IF;',
'        ELSE',
'        --  :P24_SADAD_BILLING_TYPE IS NULL OR :P24_IS_WINNING_PRICE_HAS_VAT IS NULL OR',
'            IF :P24_AUCTION_TYPE_ID IS NULL OR :P24_CATEGORY_ID IS NULL OR :P24_DEPENDENT IS NULL OR :P24_TRSYAH IS NULL OR :P24_INSURANCE_DEDUCTED IS NULL OR',
'                :P24_INSURANCE_METHOD IS NULL OR :P24_COMMISSION_TYPE_ID IS NULL OR :P24_COMMISSION IS NULL OR :P24_PAYMENT_DEADLINE IS NULL OR',
'                :P24_NAME_AR IS NULL OR :P24_VIDEO_URL IS NULL OR :P24_LOGO IS NULL OR',
'               :P24_BROCHURE IS NULL OR :P24_TERMS_AR IS NULL THEN',
'                RAISE_APPLICATION_ERROR (-20005, ''Missing Data!'');',
'            END IF;',
'            INSERT INTO AUCTION_TEMP(SELLER_ID, AUCTION_TYPE_ID, CATEGORY_ID, PRODUCT_TYPE_ID, INSURANCE_DEDUCTED, TRSYAH, INSURANCE_METHOD,',
'                                    COMMISSION, COMMISSION_TYPE_ID, PAYMENT_DEADLINE, NAME_AR, LOGO_URL, BROCHURE_URL, VIDEO_URL,',
'                                     AUCTION_TERMS_AR, IS_WINNING_PRICE_HAS_VAT, SADAD_BILL_TYPE)',
'                 VALUES (:P_SELLER_ID, :P24_AUCTION_TYPE_ID, :P24_CATEGORY_ID, :P24_DEPENDENT, :P24_INSURANCE_DEDUCTED, :P24_TRSYAH, :P24_INSURANCE_METHOD,',
'                         :P24_COMMISSION, :P24_COMMISSION_TYPE_ID, :P24_PAYMENT_DEADLINE, :P24_NAME_AR, :P24_LOGO_URL, :P24_BROCHURE_URL,',
'                         :P24_VIDEO_URL, :P24_TERMS_AR, :P24_IS_WINNING_PRICE_HAS_VAT, :P24_SADAD_BILLING_TYPE)',
'                RETURNING ID INTO :P24_AUCTION_ID;',
'            ',
'            IF SQL%Rowcount = 0 THEN',
'                RAISE_APPLICATION_ERROR (-20006, ''Server error'');',
'            END IF;',
'        END IF;',
'    END IF;',
'    IF v_count > 0 THEN',
'',
'        IF :P24_DEPENDENT = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''infath'', p_lookup_code => ''auction_dependency'') THEN ',
'                IF :P24_CATEGORY_ID = :P24_CATEGORY_PREAL_ESTATES_ID THEN',
