'                    p_c009 =>  LOOKUPS_MNT.lookup_detail_id_by_code(p_lookup_detail_code => ''percentage'', p_lookup_code => ''commission_type''),',
'                    p_c010 => :P24_PAYMENT_DEADLINE,',
'                    p_c011 => :P24_NAME_AR,',
'                    p_c012 => :P24_LOGO_URL,',
'                    p_c013 => :P24_BROCHURE_URL,',
'                    p_c014 => :P24_VIDEO_URL,',
'                    p_c015 => :P24_TERMS_AR,',
'                    p_c016 => :P24_IS_WINNING_PRICE_HAS_VAT,',
'                    p_c017 => :P24_SADAD_BILLING_TYPE);',
'                END IF; -- IF PORTABLE INFATH',
'        ELSE',
'            IF :P24_TRSYAH IS NULL OR :P24_INSURANCE_DEDUCTED IS NULL OR :P24_INSURANCE_METHOD IS NULL OR :P24_COMMISSION_TYPE_ID IS NULL OR :P24_COMMISSION IS NULL OR :P24_TERMS_AR IS NULL THEN',
'                RAISE_APPLICATION_ERROR (-20005, ''Missing Data!'');',
'            END IF; -- MISSING DATA NOT INFATH',
'            APEX_COLLECTION.update_member (',
'            p_collection_name => ''AUCTION_DETAILS'',',
'            p_seq  => 1,',
'            p_c001 => :P_SELLER_ID, ',
'            p_c002 => :P24_AUCTION_TYPE_ID, ',
'            p_c003 => :P24_CATEGORY_ID, ',
'            p_c004 => :P24_DEPENDENT, ',
'            p_c005 => :P24_INSURANCE_DEDUCTED, ',
'            p_c006 => :P24_TRSYAH, ',
'            p_c007 => :P24_INSURANCE_METHOD, ',
'            p_c008 => :P24_COMMISSION, ',
'            p_c009 => :P24_COMMISSION_TYPE_ID, ',
'            p_c010 => :P24_PAYMENT_DEADLINE, ',
'            p_c011 => :P24_NAME_AR, ',
'            p_c012 => :P24_LOGO_URL, ',
'            p_c013 => :P24_BROCHURE_URL, ',
'            p_c014 => :P24_VIDEO_URL, ',
'            p_c015 => :P24_TERMS_AR, ',
'            p_c016 => :P24_IS_WINNING_PRICE_HAS_VAT, ',
'            p_c017 => :P24_SADAD_BILLING_TYPE);',
'        END IF; -- IF INFATH',
'    END IF; -- UPDATE COLLECTION MEMBERS',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(167876022071089008)
