'        WHERE  collection_name = ''AUCTION_DETAILS'';',
'    ELSE',
'       :P24_AUCTION_ID         := NULL;',
'       :P24_AUCTION_TYPE_ID    := NULL;',
'       :P24_CATEGORY_ID        := NULL;',
'       :P24_DEPENDENT          := NULL;',
