'            :P24_AUCTION_TYPE_ID    := NULL;',
'            :P24_CATEGORY_ID        := NULL;',
'            :P24_DEPENDENT          := NULL;',
'            :P24_INSURANCE_DEDUCTED := NULL;',
'            :P24_TRSYAH             := NULL;',
'            :P24_INSURANCE_METHOD   := NULL;',
'            :P24_COMMISSION         := NULL;',
'            :P24_COMMISSION_TYPE_ID := NULL;',
