wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(57350952165078354)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload File CR'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_names        APEX_T_VARCHAR2;',
'    l_file              APEX_APPLICATION_TEMP_FILES%ROWTYPE;',
'    l_file_name         VARCHAR2(255);',
'    l_request_url	    VARCHAR2(32767);',
'    l_result	        CLOB;',
'    l_request_filename	VARCHAR2(500);',
'    l_inner_folder  	VARCHAR2(500);',
'BEGIN',
'    l_file_names := apex_string.SPLIT (',
'                        p_str => :P25_CR,',
'                        p_sep => '':'' );',
'',
'    -- IF l_file_names.count = 0 THEN',
unistr('    --     RAISE_APPLICATION_ERROR(-20001, ''\064A\062C\0628 \0639\0644\064A\0643 \0631\0641\0639 \0627\0644\062A\0642\0631\064A\0631 \0627\0644\062E\0627\0635 \0628\0643!'');'),
'    -- END IF;',
'',
'    IF :P25_CR IS NOT NULL THEN',
'        SELECT *',
'          INTO l_file',
'          FROM APEX_APPLICATION_TEMP_FILES',
'         WHERE NAME = :P25_CR;',
'',
'        l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                            || DBMS_RANDOM.STRING(''x'', 8)',
'                            || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'',
'        l_request_url := :G_OCI_BASE_URL||''/b/seller_signup/o/''||l_file_name;',
'        ',
'        l_result := APEX_WEB_SERVICE.make_rest_request (',
'                        p_url                  => l_request_url,',
'                        p_http_method          => ''PUT'',',
'                        p_body_blob            => l_file.BLOB_CONTENT,',
'                        p_credential_static_id => ''OCI_AUTH''',
'                    );',
'        l_file_name := TO_CHAR(get_current_date, ''YY''); ',
'',
'           IF APEX_WEB_SERVICE.g_status_code NOT IN ( 200, 201, 202, 203, 204, 205, 206, 207, 226 ) THEN',
'                SYSTEM_CONTROLS.ERROR_LOGS(p_ERROR_TYPE    => ''SYSTEM_ERROR'',',
'                                           p_PROCESS_NAME  => ''OCI_OS.put_object - '' || :APP_ID,',
'                                           p_ERROR_CODE    => -2,',
'                                           p_ERROR_MESSAGE => SUBSTR(l_result, 1, 4000),',
'                                           p_logger_name   => :APP_USER);',
'                RAISE_APPLICATION_ERROR(-20001, ''Error with uploading Data!'');',
'            END IF;',
'',
'        UPDATE SELLERS_REQUESTS_DETAILS',
'           SET CR_URL = l_request_url',
'         WHERE SELLER_ID = :P25_ID;',
'        ',
'    END IF;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(57437147416038612)
,p_internal_uid=>41317807485143249
);
