wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(63850834154748538)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Delete products'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_category_seller NUMBER;',
'    v_count_products  NUMBER;',
'BEGIN',
'    -- SELECT CATEGORY_ID INTO v_category_seller FROM AUCTION_TEMP WHERE SELLER_ID = :P_SELLER_ID ;',
'',
'    SELECT COUNT(1)',
'     INTO v_count_products',
'     FROM PRODUCTS_TEMP ptemp , AUCTION_TEMP atemp',
'    WHERE ptemp.SELLER_ID = :P_SELLER_ID',
'      AND ptemp.AUCTION_ID = :P26_AUCTION_ID',
'      AND atemp.CATEGORY_ID <> :P26_CATEGORY_REAL_ESTATE_ID;',
'    ',
'    IF v_count_products > 0 THEN',
'        FOR i IN (SELECT ID, PRODUCT_ID FROM PRODUCTS_TEMP WHERE AUCTION_ID = :P26_AUCTION_ID) LOOP',
'',
'            DELETE FROM PRODUCTS_TEMP WHERE AUCTION_ID = :P26_AUCTION_ID AND ID = i.ID;',
'            IF SQL%ROWCOUNT = 0 THEN',
'                RAISE_APPLICATION_ERROR(-20001, ''server error'');',
'            END IF;',
'',
'            UPDATE PRODUCTS',
'              SET STATUS = LOOKUPS_MNT.lookup_detail_id_by_code( p_lookup_detail_code => ''available'',  p_lookup_code => ''product_status'')',
'            WHERE ID = i.PRODUCT_ID;',
'            IF SQL%ROWCOUNT = 0 THEN',
'                RAISE_APPLICATION_ERROR(-20002, ''server error'');',
'            END IF;',
'',
'        END LOOP;',
'    END IF;',
'END;',
'',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(162214912855685671)
,p_process_when_type=>'NEVER'
,p_internal_uid=>47817689474813433
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(60366314153371749)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insert products'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_product_id       NUMBER;',
'    v_product_name     VARCHAR2(255);',
'    v_count          NUMBER;',
'    v_count_seller   NUMBER;',
'    v_count_products NUMBER;',
'    v_lane_no        NUMBER;',
'BEGIN',
'    v_lane_no := 1;',
'    SELECT COUNT(1) INTO v_count_seller FROM AUCTION_TEMP WHERE SELLER_ID = :P_SELLER_ID;',
'    SELECT COUNT(1) INTO v_count_products FROM PRODUCTS_TEMP WHERE SELLER_ID = :P_SELLER_ID AND AUCTION_ID = :P26_AUCTION_ID;',
'    ',
'    IF v_count_products = 0 THEN',
'        IF :P26_INSURANCE IS NULL THEN',
'            RAISE_APPLICATION_ERROR (-20001, ''Missing Data'');',
'        END IF;',
'',
'        IF APEX_APPLICATION.g_f01.count = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20002, ''need to add products'');',
'        END IF;',
'',
'        FOR i IN 1..APEX_APPLICATION.g_f01.count LOOP',
'           SELECT ID, NAME_AR INTO v_product_id, v_product_name FROM PRODUCTS WHERE ID = APEX_APPLICATION.g_f01(i);',
'',
'           IF :P26_CATEGORY_ID = :P26_CATEGORY_PORTABLE_ID OR',
'             (:P26_CATEGORY_ID = :P26_CATEGORY_REAL_ESTATE_ID AND',
'              :P26_IS_INFATH = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''infath'', p_lookup_code => ''auction_dependency'')) THEN',
'               INSERT INTO PRODUCTS_TEMP(SELLER_ID, AUCTION_ID, PRODUCT_ID, PRODUCT_NAME, IS_METER_OR_PRICE, METER_PRICE, INSURANCE, START_PRICE,',
'                                         EVERY_CLICK, ALLOW_SELL_PRICE, BUY_NOW_PRICE, START_DATE, END_DATE, PRODUCT_TERMS_AR, LANE_NO)',
'                    VALUES(:P_SELLER_ID, :P26_AUCTION_ID, v_product_id, v_product_name, :P26_TOTAL_PRICE_ID, NULL, :P26_INSURANCE, :P26_START_PRICE,',
'                         :P26_EVERY_CLICK, :P26_ALLOW_SELL_PRICE, :P26_BUY_NOW_PRICE, :P26_START_DATE, :P26_END_DATE, :P26_PRODUCT_TERMS_AR, v_lane_no);',
'',
'                IF SQL%ROWCOUNT = 0 THEN',
'                    RAISE_APPLICATION_ERROR(-20003, ''server error'');',
'                END IF;',
'                    v_lane_no := v_lane_no + 1;',
'            ELSE',
'               INSERT INTO PRODUCTS_TEMP(SELLER_ID, AUCTION_ID, PRODUCT_ID, PRODUCT_NAME, IS_METER_OR_PRICE, METER_PRICE, INSURANCE, START_PRICE,',
'                                         EVERY_CLICK, ALLOW_SELL_PRICE, BUY_NOW_PRICE, START_DATE, END_DATE, PRODUCT_TERMS_AR, LANE_NO)',
'                    VALUES(:P_SELLER_ID, :P26_AUCTION_ID, v_product_id, v_product_name, :P26_TOTAL_OR_METER, :P26_METER_PRICE, :P26_INSURANCE, :P26_START_PRICE,',
'                         :P26_EVERY_CLICK, :P26_ALLOW_SELL_PRICE, :P26_BUY_NOW_PRICE, :P26_START_DATE, :P26_END_DATE, :P26_PRODUCT_TERMS_AR, v_lane_no);',
'                IF SQL%ROWCOUNT = 0 THEN',
'                    RAISE_APPLICATION_ERROR(-20004, ''server error'');',
'                END IF;',
'                v_lane_no := v_lane_no + 1;',
'            END IF;',
'            UPDATE PRODUCTS',
'               SET STATUS = LOOKUPS_MNT.lookup_detail_id_by_code( p_lookup_detail_code => ''on_auction'',  p_lookup_code => ''product_status'')',
'             WHERE ID = v_product_id ;',
'',
'            IF SQL%ROWCOUNT = 0 THEN',
'                  RAISE_APPLICATION_ERROR(-20005, ''server error'');',
'            END IF;',
'',
'            SELECT COUNT(SEQ_ID) INTO v_count FROM APEX_COLLECTIONS WHERE COLLECTION_NAME = ''EXTRA_EXPENSES'';',
'            IF  v_count > 0 THEN ',
'                FOR i IN ( SELECT c001, c002, c003 FROM APEX_COLLECTIONS WHERE COLLECTION_NAME = ''EXTRA_EXPENSES'' ORDER BY SEQ_ID ) LOOP',
'                    INSERT INTO EXTRA_EXPENSES_IN_TIMED_AUCTION ( PRODUCT_ID, SELLER_ID, NAME_AR, VALUE, TYPE_ID, AUCTION_ID  )',
'                        VALUES ( v_product_id, :P_SELLER_ID, i.c001, i.c002, i.c003, :P26_AUCTION_ID );',
'                    ',
'                    IF SQL%ROWCOUNT = 0 THEN',
'                        RAISE_APPLICATION_ERROR(-20006, ''EROOR'');',
'                    END IF;',
'               END LOOP;  ',
'            END IF;',
'        END LOOP;',
'',
'        IF  v_count > 0 THEN ',
'            APEX_COLLECTION.truncate_collection ( p_collection_name => ''EXTRA_EXPENSES'' );',
'        END IF;',
'    ELSE',
'        FOR i IN 1..APEX_APPLICATION.g_f01.count LOOP',
'           SELECT ID, NAME_AR INTO v_product_id, v_product_name FROM PRODUCTS WHERE ID = APEX_APPLICATION.g_f01(i);',
'           SELECT MAX(LANE_NO) INTO v_lane_no FROM PRODUCTS_TEMP WHERE AUCTION_ID = :P26_AUCTION_ID;',
'',
'           IF :P26_CATEGORY_ID = :P26_CATEGORY_PORTABLE_ID OR',
'             (:P26_CATEGORY_ID = :P26_CATEGORY_REAL_ESTATE_ID AND',
'              :P26_IS_INFATH = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''infath'', p_lookup_code => ''auction_dependency'')) THEN',
'               v_lane_no := v_lane_no + 1;',
'               INSERT INTO PRODUCTS_TEMP(SELLER_ID, AUCTION_ID, PRODUCT_ID, PRODUCT_NAME, IS_METER_OR_PRICE, METER_PRICE, INSURANCE, START_PRICE,',
'                                         EVERY_CLICK, ALLOW_SELL_PRICE, BUY_NOW_PRICE, START_DATE, END_DATE, PRODUCT_TERMS_AR, LANE_NO)',
'                    VALUES(:P_SELLER_ID, :P26_AUCTION_ID, v_product_id, v_product_name, :P26_TOTAL_PRICE_ID, NULL, :P26_INSURANCE, :P26_START_PRICE,',
'                         :P26_EVERY_CLICK, :P26_ALLOW_SELL_PRICE, :P26_BUY_NOW_PRICE, :P26_START_DATE, :P26_END_DATE, :P26_PRODUCT_TERMS_AR, v_lane_no);',
'                IF SQL%ROWCOUNT = 0 THEN',
'                    RAISE_APPLICATION_ERROR(-20003, ''server error'');',
'                END IF;',
'            ELSE',
'               v_lane_no := v_lane_no + 1;',
'               INSERT INTO PRODUCTS_TEMP(SELLER_ID, AUCTION_ID, PRODUCT_ID, PRODUCT_NAME, IS_METER_OR_PRICE, METER_PRICE, INSURANCE, START_PRICE,',
'                                         EVERY_CLICK, ALLOW_SELL_PRICE, BUY_NOW_PRICE, START_DATE, END_DATE, PRODUCT_TERMS_AR, LANE_NO)',
'                    VALUES(:P_SELLER_ID, :P26_AUCTION_ID, v_product_id, v_product_name, :P26_TOTAL_OR_METER, :P26_METER_PRICE, :P26_INSURANCE, :P26_START_PRICE,',
'                         :P26_EVERY_CLICK, :P26_ALLOW_SELL_PRICE, :P26_BUY_NOW_PRICE, :P26_START_DATE, :P26_END_DATE, :P26_PRODUCT_TERMS_AR, v_lane_no);',
'                IF SQL%ROWCOUNT = 0 THEN',
'                    RAISE_APPLICATION_ERROR(-20004, ''server error'');',
'                END IF;',
'            END IF;',
'',
'            UPDATE PRODUCTS',
'               SET STATUS = LOOKUPS_MNT.lookup_detail_id_by_code( p_lookup_detail_code => ''on_auction'',  p_lookup_code => ''product_status'')',
'             WHERE ID = v_product_id ;',
'',
'            IF SQL%ROWCOUNT = 0 THEN',
'                  RAISE_APPLICATION_ERROR(-20005, ''server error'');',
'            END IF;',
'            SELECT COUNT(SEQ_ID) INTO v_count FROM APEX_COLLECTIONS WHERE COLLECTION_NAME = ''EXTRA_EXPENSES'';',
'',
'            IF v_count > 0 THEN ',
'                FOR i IN ( SELECT c001, c002, c003 FROM APEX_COLLECTIONS WHERE COLLECTION_NAME = ''EXTRA_EXPENSES'' ORDER BY SEQ_ID ) LOOP',
'                    INSERT INTO EXTRA_EXPENSES_IN_TIMED_AUCTION ( PRODUCT_ID, SELLER_ID, NAME_AR, VALUE, TYPE_ID, AUCTION_ID  )',
'                        VALUES ( v_product_id, :P_SELLER_ID, i.c001, i.c002, i.c003, :P26_AUCTION_ID );',
'                    ',
'                    IF SQL%ROWCOUNT = 0 THEN',
'                        RAISE_APPLICATION_ERROR(-20006, ''EROOR'');',
'                    END IF;',
'               END LOOP;  ',
'            END IF;',
'        END LOOP;',
'',
'        IF v_count > 0 THEN ',
'            APEX_COLLECTION.truncate_collection ( p_collection_name => ''EXTRA_EXPENSES'' );',
'        END IF;',
'    END IF;',
'END;',
'',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(162214912855685671)
,p_process_when_type=>'NEVER'
,p_internal_uid=>44333169473436644
