 p_id=>wwv_flow_imp.id(25361615782140323)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insert products collection '
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_product_id   NUMBER;',
'    v_product_name VARCHAR2(255);',
'    v_lane_no      NUMBER;',
'    v_count        NUMBER;',
'    v_count_product NUMBER;',
'BEGIN',
'       v_lane_no := 1;',
'        IF :P26_INSURANCE IS NULL THEN',
'            RAISE_APPLICATION_ERROR (-20001, ''Missing Data'');',
'        END IF;',
'',
'        IF NOT APEX_COLLECTION.collection_exists(''PRODUCT_DETAILS'') THEN',
'            IF APEX_APPLICATION.g_f01.count = 0 THEN',
'                RAISE_APPLICATION_ERROR(-20002, ''need to add products'');',
'            END IF;',
'        ELSE  ',
'            SELECT COUNT(1), (MAX(n002) +1)',
'              INTO v_count_product, v_lane_no',
'              FROM APEX_COLLECTIONS',
'              WHERE collection_name = ''PRODUCT_DETAILS'';',
'',
'               IF v_count_product = 0 THEN ',
'                    RAISE_APPLICATION_ERROR(-20007, ''need to add products'');',
'                END IF;',
'        END IF;',
'        ',
'        FOR i IN 1..APEX_APPLICATION.g_f01.count LOOP',
'            SELECT ID, NAME_AR',
'              INTO v_product_id, v_product_name',
'              FROM PRODUCTS',
'             WHERE ID = APEX_APPLICATION.g_f01(i);',
'            IF :P26_CATEGORY_ID = :P26_CATEGORY_PORTABLE_ID OR ',
'              (:P26_CATEGORY_ID = :P26_CATEGORY_REAL_ESTATE_ID AND :P26_IS_INFATH = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''infath'', p_lookup_code => ''auction_dependency'')) THEN',
'                IF NOT APEX_COLLECTION.collection_exists(''PRODUCT_DETAILS'') THEN',
'                   APEX_COLLECTION.create_collection(''PRODUCT_DETAILS'');',
'                    APEX_COLLECTION.add_member (',
'                        p_collection_name => ''PRODUCT_DETAILS'',',
'                        p_c001 => :P_SELLER_ID,',
'                        p_c002 => :P26_AUCTION_ID,',
'                        p_c003 => v_product_id,',
'                        p_c004 => v_product_name,',
'                        p_c005 => LOOKUPS_MNT.lookup_detail_id_by_code(p_lookup_detail_code => ''total_price'', p_lookup_code => ''pricing_type''),',
'                        p_c006 => NULL,',
'                        p_c007 => :P26_INSURANCE,',
'                        p_c008 => :P26_START_PRICE,',
'                        p_c009 => :P26_EVERY_CLICK,',
'                        p_c010 => :P26_ALLOW_SELL_PRICE,',
'                        p_c011 => :P26_BUY_NOW_PRICE,',
'                        p_c012 => :P26_START_DATE,',
'                        p_c013 => :P26_END_DATE,',
'                        p_c014 => :P26_PRODUCT_TERMS_AR,',
'                        p_n001 => 0,',
'                        p_n002 =>  v_lane_no);',
'                ELSE',
'                    APEX_COLLECTION.add_member (',
'                        p_collection_name => ''PRODUCT_DETAILS'',',
'                        p_c001 => :P_SELLER_ID,',
'                        p_c002 => :P26_AUCTION_ID,',
'                        p_c003 => v_product_id,',
'                        p_c004 => v_product_name,',
'                        p_c005 => LOOKUPS_MNT.lookup_detail_id_by_code(p_lookup_detail_code => ''total_price'', p_lookup_code => ''pricing_type''),',
'                        p_c006 => NULL,',
'                        p_c007 => :P26_INSURANCE,',
'                        p_c008 => :P26_START_PRICE,',
'                        p_c009 => :P26_EVERY_CLICK,',
'                        p_c010 => :P26_ALLOW_SELL_PRICE,',
'                        p_c011 => :P26_BUY_NOW_PRICE,',
'                        p_c012 => :P26_START_DATE,',
'                        p_c013 => :P26_END_DATE,',
'                        p_c014 => :P26_PRODUCT_TERMS_AR,',
'                        p_n001 => 0,',
'                        p_n002 =>  v_lane_no);',
'                END IF;',
'                    v_lane_no := v_lane_no + 1;',
'            ELSE',
'                IF NOT APEX_COLLECTION.collection_exists(''PRODUCT_DETAILS'') THEN',
'                   APEX_COLLECTION.create_collection(''PRODUCT_DETAILS'');',
'                    APEX_COLLECTION.add_member (',
'                        p_collection_name => ''PRODUCT_DETAILS'',',
'                        p_c001 => :P_SELLER_ID,',
'                        p_c002 => :P26_AUCTION_ID,',
'                        p_c003 =>  v_product_id,',
'                        p_c004 =>  v_product_name,',
'                        p_c005 => :P26_TOTAL_OR_METER,',
'                        p_c006 => :P26_METER_PRICE,',
'                        p_c007 => :P26_INSURANCE,',
'                        p_c008 => :P26_START_PRICE,',
'                        p_c009 => :P26_EVERY_CLICK,',
'                        p_c010 => :P26_ALLOW_SELL_PRICE,',
'                        p_c011 => :P26_BUY_NOW_PRICE,',
'                        p_c012 => :P26_START_DATE,',
'                        p_c013 => :P26_END_DATE,',
'                        p_c014 => :P26_PRODUCT_TERMS_AR,',
'                        p_n001 => 0,',
'                        p_n002 =>  v_lane_no);',
'                    ELSE',
'                    APEX_COLLECTION.add_member (',
'                        p_collection_name => ''PRODUCT_DETAILS'',',
'                        p_c001 => :P_SELLER_ID,',
'                        p_c002 => :P26_AUCTION_ID,',
'                        p_c003 =>  v_product_id,',
'                        p_c004 =>  v_product_name,',
'                        p_c005 => :P26_TOTAL_OR_METER,',
'                        p_c006 => :P26_METER_PRICE,',
'                        p_c007 => :P26_INSURANCE,',
'                        p_c008 => :P26_START_PRICE,',
'                        p_c009 => :P26_EVERY_CLICK,',
'                        p_c010 => :P26_ALLOW_SELL_PRICE,',
'                        p_c011 => :P26_BUY_NOW_PRICE,',
'                        p_c012 => :P26_START_DATE,',
'                        p_c013 => :P26_END_DATE,',
'                        p_c014 => :P26_PRODUCT_TERMS_AR,',
