'            END IF;',
'',
'            SELECT COUNT(SEQ_ID) INTO v_count FROM APEX_COLLECTIONS WHERE COLLECTION_NAME = ''EXTRA_EXPENSES'';',
'            IF  v_count > 0 THEN ',
'                FOR i IN ( SELECT c001, c002, c003 FROM APEX_COLLECTIONS WHERE COLLECTION_NAME = ''EXTRA_EXPENSES'' ORDER BY SEQ_ID ) LOOP',
'                    IF NOT APEX_COLLECTION.collection_exists(''PRODUCTS_EXPENSES'') THEN',
'                        APEX_COLLECTION.create_collection(''PRODUCTS_EXPENSES'');',
'                        APEX_COLLECTION.add_member (',
'                        p_collection_name => ''PRODUCTS_EXPENSES'',',
'                        p_c001 => v_product_id,',
'                        p_c002 => :P_SELLER_ID,',
'                        p_c003 => i.c001,-- NAME',
'                        p_c004 => i.c002, -- VALUE',
'                        p_c005 => i.c003); -- TYPE',
'                    ELSE',
'                        APEX_COLLECTION.add_member (',
'                        p_collection_name => ''PRODUCTS_EXPENSES'',',
'                        p_c001 => v_product_id,',
'                        p_c002 => :P_SELLER_ID,',
'                        p_c003 => i.c001,',
'                        p_c004 => i.c002,',
'                        p_c005 => i.c003);',
'                    END IF; -- PRODUCT EXPENSE',
'               END LOOP; --EXPENSES LOOP',
'            END IF; -- IF COUNT ',
'        END LOOP; --INSERT LOOP',
'        IF  v_count > 0 THEN ',
'            APEX_COLLECTION.truncate_collection ( p_collection_name => ''EXTRA_EXPENSES'' );',
'        END IF;',
