wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(62514701137826216)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Send auction details'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_auction_id         NUMBER;',
'    v_product_id         NUMBER;',
'    v_seller_id          VARCHAR2(255);',
'    v_auction_type_id    VARCHAR2(255);',
'    v_category_id        VARCHAR2(255);',
'    v_product_type_id    VARCHAR2(255);',
'    v_insurance_deducted VARCHAR2(255);',
'    v_trsyah             VARCHAR2(255);',
'    v_insurance_method   VARCHAR2(255);',
'    v_commission         VARCHAR2(255);',
'    v_commission_type_id VARCHAR2(255);',
'    v_payment_deadline   VARCHAR2(255);',
'    v_name_ar            VARCHAR2(255);',
'    v_seller_name_ar     VARCHAR2(255);',
'    v_seller_name_en     VARCHAR2(255);',
'    v_seller_logo_url    VARCHAR2(2000);',
'    v_logo_url           VARCHAR2(2000);',
'    v_brochure_url       VARCHAR2(2000);',
'    v_video_url          VARCHAR2(2000);',
'    v_auction_terms_ar   VARCHAR2(5000);',
'    l_result             VARCHAR2(5000);',
'    l_message            VARCHAR2(5000);',
'    header               json_object_t;',
'    seller_object        json_object_t;',
'    products_object      json_object_t;',
'    expenses_object      json_object_t;',
'    auction_array        json_array_t;',
'    product_array        json_array_t;',
'    expenses_array       json_array_t;',
'    v_sadad_billing_type VARCHAR2(255);',
'    -- v_is_auto_generate_commission_invoice VARCHAR2(255); ',
'    v_is_winning_price_has_vat VARCHAR2(255);',
'BEGIN',
'    header          := json_object_t();',
'    seller_object   := json_object_t();',
'    products_object := json_object_t();',
'    expenses_object := json_object_t();',
'    auction_array   := json_array_t();',
'    product_array   := json_array_t();',
'    expenses_array  := json_array_t();',
'',
'    SELECT ID, SELLER_ID, UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => AUCTION_TYPE_ID)), CATEGORY_ID,',
'           UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => PRODUCT_TYPE_ID)), DECODE(INSURANCE_DEDUCTED, 1, ''TRUE'', ''FALSE''),',
'           DECODE(TRSYAH, 1, ''TRUE'', ''FALSE''), UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => INSURANCE_METHOD)) AS INSURANCE_METHOD,',
'           COMMISSION, UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => COMMISSION_TYPE_ID)), PAYMENT_DEADLINE, NAME_AR, LOGO_URL,',
'           BROCHURE_URL, VIDEO_URL, AUCTION_TERMS_AR, DECODE(IS_WINNING_PRICE_HAS_VAT, 1, ''TRUE'', ''FALSE''),UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => SADAD_BILL_TYPE)) ',
'      INTO v_auction_id, v_seller_id, v_auction_type_id, v_category_id, v_product_type_id, v_insurance_deducted, v_trsyah, v_insurance_method, ',
'           v_commission, v_commission_type_id, v_payment_deadline, v_name_ar, v_logo_url, v_brochure_url, v_video_url, v_auction_terms_ar,',
'           v_is_winning_price_has_vat, v_sadad_billing_type',
'      FROM AUCTION_TEMP',
'     WHERE SELLER_ID = :P_SELLER_ID;',
'',
'    SELECT NAME_AR, NAME_EN, AVATAR_URL',
'      INTO v_seller_name_ar, v_seller_name_en, v_seller_logo_url',
'      FROM SELLERS',
'     WHERE ID = :P_SELLER_ID;',
'',
'    seller_object.put(''id'',       :P_SELLER_ID);',
'    seller_object.put(''nameAr'',   v_seller_name_ar);',
'    seller_object.put(''nameEn'',   v_seller_name_en);',
'    seller_object.put(''imageUrl'', v_seller_logo_url);',
'',
'    header.put(''seller'',                        seller_object);',
'    header.put(''type'',                          TRIM(v_auction_type_id));',
'    header.put(''category'',                      TRIM(v_category_id));',
'    header.put(''auctionHost'',                   TRIM(v_product_type_id));',
'    header.put(''insurance_deducted'',            TRIM(v_insurance_deducted));',
'    header.put(''autoAwarding'',                  TRIM(v_trsyah));',
'    header.put(''autoGenerateFullInvoice'',       TRIM(v_sadad_billing_type));',
'    -- header.put(''autoGenerateCommissionInvoice'', TRIM(v_is_auto_generate_commission_invoice));',
'    header.put(''winningPriceHasVat'',            TRIM(v_is_winning_price_has_vat));',
'    header.put(''insuranceMethods'',              TRIM(v_insurance_method));',
'    header.put(''commission'',                    TRIM(v_commission));',
'    header.put(''commissionType'',                TRIM(v_commission_type_id));',
'    header.put(''paymentDeadline'',               TRIM(v_payment_deadline));',
'    header.put(''nameAr'',                        TRIM(v_name_ar));',
'    header.put(''imageUrl'',                      TRIM(v_logo_url));',
'    header.put(''brochure'',                      TRIM(v_brochure_url));',
'    header.put(''videoUrl'',                      TRIM(v_video_url));',
'    header.put(''termsAndConditionsAr'',          TRIM(v_auction_terms_ar));',
'',
'    FOR i IN (SELECT SELLER_ID, PRODUCT_ID, UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => IS_METER_OR_PRICE)) IS_METER_OR_PRICE,',
'                     INSURANCE, START_PRICE, EVERY_CLICK, ALLOW_SELL_PRICE, BUY_NOW_PRICE, PRODUCT_TERMS_AR, START_DATE, END_DATE, LANE_NO',
'                     FROM PRODUCTS_TEMP',
'                    WHERE SELLER_ID = :P_SELLER_ID',
'                      AND AUCTION_ID = v_auction_id)',
'    LOOP',
'        FOR j IN (SELECT SELLER_ID, AUCTION_ID, PRODUCT_ID, NAME_AR, VALUE, UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => TYPE_ID)) AS TYPE_ID',
'                         FROM EXTRA_EXPENSES_IN_TIMED_AUCTION',
'                        WHERE SELLER_ID = :P_SELLER_ID',
'                          AND PRODUCT_ID = i.PRODUCT_ID )',
'        LOOP',
'            expenses_object.put(''nameAr'', TRIM(j.NAME_AR));',
'            expenses_object.put(''amount'', TRIM(j.VALUE));',
'            expenses_object.put(''type'',   TRIM(j.TYPE_ID));',
'',
'            expenses_array.append(expenses_object); ',
'            expenses_object := json_object_t();        ',
'        END LOOP; --EXTRA',
'            products_object.put(''product'',                  TRIM(i.PRODUCT_ID));',
'            products_object.put(''pricingType'',              TRIM(i.IS_METER_OR_PRICE));',
'            products_object.put(''insurance'',                TRIM(i.INSURANCE));',
'            products_object.put(''auctionOpeningPrice'',      TRIM(i.START_PRICE));',
'            products_object.put(''mimimumBid'',               TRIM(i.EVERY_CLICK));',
'            products_object.put(''minimumAcceptablePrice'',   TRIM(i.ALLOW_SELL_PRICE));',
'            products_object.put(''buyNowPrice'',              TRIM(i.BUY_NOW_PRICE));',
'            products_object.put(''termsAndConditionsAr'',     TRIM(i.PRODUCT_TERMS_AR));',
'            products_object.put(''startDateAndTime'',         TRIM(SYSTEM_CONTROLS.date_to_unix ( p_date => i.START_DATE)));',
'            products_object.put(''closingDateAndTime'',       TRIM(SYSTEM_CONTROLS.date_to_unix ( p_date => i.END_DATE)));',
'            products_object.put(''sequence'',                 TRIM(i.LANE_NO));',
'            products_object.put(''extraExpenses'',            expenses_array);',
'',
'            product_array.append(products_object); ',
'            products_object := json_object_t();',
'            expenses_array  := json_array_t();',
'    END LOOP; --PRODUCT',
'',
'    header.put(''auctions'', product_array);',
'',
'    l_result := SYSTEM_INTEGRATION.send_auction (',
'                        p_body     => header.to_clob(),',
'                        p_message  => l_message',
'                    );',
'',
'    products_object := json_object_t();',
'    expenses_object := json_object_t();',
'    seller_object   := json_object_t();',
'    product_array   := json_array_t();',
'    expenses_array  := json_array_t();',
'',
'    IF l_result <> ''1'' THEN',
'        RAISE_APPLICATION_ERROR(-20003, l_message);',
'    END IF;',
'END;',
'-- DECLARE',
'--     v_auction_id         NUMBER;',
'--     v_product_id         NUMBER;',
'--     v_seller_id          VARCHAR2(255);',
'--     v_auction_type_id    VARCHAR2(255);',
'--     v_category_id        VARCHAR2(255);',
'--     v_product_type_id    VARCHAR2(255);',
'--     v_insurance_deducted VARCHAR2(255);',
