,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Clear temps'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    DELETE FROM EXTRA_EXPENSES_IN_TIMED_AUCTION WHERE SELLER_ID = :P_SELLER_ID AND AUCTION_ID = :P28_AUCTION_ID;',
'    DELETE FROM PRODUCTS_TEMP WHERE SELLER_ID = :P_SELLER_ID AND AUCTION_ID = :P28_AUCTION_ID;',
'    DELETE FROM AUCTION_TEMP WHERE SELLER_ID = :P_SELLER_ID;',
'END;'))
