,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_auction_id         NUMBER;',
'    v_product_id         NUMBER;',
'    v_seller_id          VARCHAR2(255);',
'    v_auction_type_id    VARCHAR2(255);',
'    v_category_id        VARCHAR2(255);',
'    v_product_type_id    VARCHAR2(255);',
'    v_insurance_deducted VARCHAR2(255);',
'    v_trsyah             VARCHAR2(255);',
'    v_insurance_method   VARCHAR2(255);',
'    v_commission         VARCHAR2(255);',
'    v_commission_type_id VARCHAR2(255);',
'    v_payment_deadline   VARCHAR2(255);',
'    v_name_ar            VARCHAR2(255);',
'    v_seller_name_ar     VARCHAR2(255);',
'    v_seller_name_en     VARCHAR2(255);',
'    v_seller_logo_url    VARCHAR2(2000);',
'    v_logo_url           VARCHAR2(2000);',
'    v_brochure_url       VARCHAR2(2000);',
'    v_video_url          VARCHAR2(2000);',
'    v_auction_terms_ar   VARCHAR2(5000);',
'    l_result             VARCHAR2(5000);',
'    l_message            VARCHAR2(5000);',
'    header               json_object_t;',
'    seller_object        json_object_t;',
'    products_object      json_object_t;',
'    expenses_object      json_object_t;',
'    auction_array        json_array_t;',
'    product_array        json_array_t;',
'    expenses_array       json_array_t;',
'    v_sadad_billing_type VARCHAR2(255);',
'    -- v_is_auto_generate_commission_invoice VARCHAR2(255); ',
'    v_is_winning_price_has_vat VARCHAR2(255);',
'BEGIN',
'    header          := json_object_t();',
'    seller_object   := json_object_t();',
'    products_object := json_object_t();',
'    expenses_object := json_object_t();',
'    auction_array   := json_array_t();',
'    product_array   := json_array_t();',
'    expenses_array  := json_array_t();',
'',
'    SELECT SEQ_ID,--ID',
'           c001,--SELLER_ID',
'           UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => c002)) AUCTION_TYPE_ID,',
'           c003,--CATEGORY_ID',
'           UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => c004)) PRODUCT_TYPE_ID,',
'           DECODE(c005,1,''TRUE'', ''FALSE''),--INSURANCE_DEDUCTED',
'           DECODE(c006, 1,''TRUE'',''FALSE''),--TRSYAH',
'            UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id =>c007 )) INSURANCE_METHOD,',
'           c008,--COMMISSION',
'           UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => c009)) COMMISSION_TYPE_ID,',
'           c010,--PAYMENT_DEADLINE',
'           c011,--NAME_AR',
'           c012,--LOGO_URL',
'           c013,--BROCHURE_URL',
'           c014,--VIDEO_URL',
'           c015,--AUCTION_TERMS_AR',
'           DECODE(c016,1,''TRUE'',''FALSE''),--IS_WINNING_PRICE_HAS_VAT',
'           UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => c017)) SADAD_BILL_TYPE',
'      INTO v_auction_id,',
'           v_seller_id,',
'           v_auction_type_id,',
'           v_category_id,',
'           v_product_type_id,',
'           v_insurance_deducted,',
'           v_trsyah,',
'           v_insurance_method,',
'           v_commission,',
'           v_commission_type_id,',
'           v_payment_deadline,',
'           v_name_ar,',
'           v_logo_url,',
'           v_brochure_url,',
'           v_video_url,',
'           v_auction_terms_ar,',
'           v_is_winning_price_has_vat,',
'           v_sadad_billing_type',
'      FROM APEX_COLLECTIONS',
'     WHERE collection_name = ''AUCTION_DETAILS'';',
'',
'    SELECT NAME_AR, NAME_EN, AVATAR_URL',
'      INTO v_seller_name_ar, v_seller_name_en, v_seller_logo_url',
'      FROM SELLERS',
'     WHERE ID = :P_SELLER_ID;',
'',
'    seller_object.put(''id'',       :P_SELLER_ID);',
'    seller_object.put(''nameAr'',   v_seller_name_ar);',
'    seller_object.put(''nameEn'',   v_seller_name_en);',
'    seller_object.put(''imageUrl'', v_seller_logo_url);',
'',
'    header.put(''seller'',                        seller_object);',
'    header.put(''type'',                          TRIM(v_auction_type_id));',
'    header.put(''category'',                      TRIM(v_category_id));',
'    header.put(''auctionHost'',                   TRIM(v_product_type_id));',
'    header.put(''insurance_deducted'',            TRIM(v_insurance_deducted));',
'    header.put(''autoAwarding'',                  TRIM(v_trsyah));',
'    header.put(''autoGenerateFullInvoice'',       TRIM(v_sadad_billing_type));',
'    -- header.put(''autoGenerateCommissionInvoice'', TRIM(v_is_auto_generate_commission_invoice));',
'    header.put(''winningPriceHasVat'',            TRIM(v_is_winning_price_has_vat));',
'    header.put(''insuranceMethods'',              TRIM(v_insurance_method));',
'    header.put(''commission'',                    TRIM(v_commission));',
'    header.put(''commissionType'',                TRIM(v_commission_type_id));',
'    header.put(''paymentDeadline'',               TRIM(v_payment_deadline));',
'    header.put(''nameAr'',                        TRIM(v_name_ar));',
'    header.put(''imageUrl'',                      TRIM(v_logo_url));',
'    header.put(''brochure'',                      TRIM(v_brochure_url));',
'    header.put(''videoUrl'',                      TRIM(v_video_url));',
'    header.put(''termsAndConditionsAr'',          TRIM(v_auction_terms_ar));',
'',
'        -- RAISE_APPLICATION_ERROR(-20009, header.to_clob);',
'',
'    FOR i IN (SELECT c001,c003,UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => c005)) IS_METER_OR_PRICE, c006, c007, c008, c009, c010, c011, c014, c012, c013, n002 ',
'                FROM APEX_COLLECTIONS',
'               WHERE collection_name = ''PRODUCT_DETAILS''',
'                 AND c001 = :P_SELLER_ID)',
'    LOOP',
'        FOR j IN (SELECT c001, c002, c003, c004, UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => c005)) AS TYPE_ID',
'                         FROM APEX_COLLECTIONS',
'                        WHERE collection_name = ''PRODUCTS_EXPENSES''',
'                          AND c002 = :P_SELLER_ID',
'                          AND c001 = i.c003)',
'        LOOP',
'            expenses_object.put(''nameAr'', TRIM(j.c003));',
'            expenses_object.put(''amount'', TRIM(j.c004));',
'            expenses_object.put(''type'',   TRIM(j.TYPE_ID));',
'',
'            expenses_array.append(expenses_object); ',
'            expenses_object := json_object_t();        ',
'        END LOOP; --EXTRA',
'            products_object.put(''product'',                  TRIM(i.c003));',
'            products_object.put(''nameAr'',                   ''product name'');',
'            products_object.put(''pricingType'',              TRIM(i.IS_METER_OR_PRICE));',
'            products_object.put(''meterPrice'',               TRIM(i.c006));',
'            products_object.put(''insurance'',                TRIM(i.c007));',
'            products_object.put(''auctionOpeningPrice'',      TRIM(i.c008));',
'            products_object.put(''mimimumBid'',               TRIM(i.c009));',
'            products_object.put(''minimumAcceptablePrice'',   TRIM(i.c010));',
'            products_object.put(''buyNowPrice'',              TRIM(i.c011));',
'            products_object.put(''termsAndConditionsAr'',     TRIM(i.c014));',
'            products_object.put(''startDateAndTime'',         TRIM(SYSTEM_CONTROLS.date_to_unix ( p_date => i.c012)));',
'            products_object.put(''closingDateAndTime'',       TRIM(SYSTEM_CONTROLS.date_to_unix ( p_date => i.c013)));',
'            products_object.put(''sequence'',                 TRIM(i.n002));',
'            products_object.put(''extraExpenses'',            expenses_array);',
'',
'            product_array.append(products_object);',
'            products_object := json_object_t();',
'            expenses_array  := json_array_t();',
'    END LOOP; --PRODUCT',
'',
'    header.put(''auctions'', product_array);',
'-- RAISE_APPLICATION_ERROR(-20009, header.to_clob);',
'    l_result := SYSTEM_INTEGRATION.send_auction (',
'                        p_body     => header.to_clob(),',
'                        p_message  => l_message',
'                    );',
'',
'    products_object := json_object_t();',
'    expenses_object := json_object_t();',
'    seller_object   := json_object_t();',
'    product_array   := json_array_t();',
'    expenses_array  := json_array_t();',
'',
'    IF l_result <> ''1'' THEN',
'        RAISE_APPLICATION_ERROR(-20007, l_message);',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_type=>'NEVER'
,p_internal_uid=>10262543615365837
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(31886202984608733)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update products'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    FOR i IN (SELECT c003 FROM APEX_COLLECTIONS WHERE collection_name = ''PRODUCT_DETAILS'') LOOP',
'    UPDATE PRODUCTS',
'       SET IN_AUCTION_COUNT = IN_AUCTION_COUNT + 1',
'     WHERE ID = i.c003;',
'    END LOOP;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>15853058304673628
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(26295764735300943)
,p_process_sequence=>70
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Clear collections'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN ',
'    IF APEX_COLLECTION.collection_exists(''PRODUCTS_EXPENSES'') THEN',
'    APEX_COLLECTION.truncate_collection ( p_collection_name => ''PRODUCTS_EXPENSES'' );',
'    END IF;',
'    APEX_COLLECTION.truncate_collection ( p_collection_name => ''PRODUCT_DETAILS'' );',
'    APEX_COLLECTION.truncate_collection ( p_collection_name => ''AUCTION_DETAILS'' );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>10262620055365838
);
end;
