,p_item_source_plug_id=>wwv_flow_imp.id(26191708204834524)
,p_prompt=>'Pricing Type'
,p_source=>'PRODUCT_PRICING_TYPE'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_RADIOGROUP'
,p_named_lov=>'PRICING_TYPE'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
' SELECT DECODE(NVL(:P_LANG, ''ar''), ''ar'', NAME_AR, NAME_EN) AS D,',
'       ID AS R',
'  FROM LOOKUP_DETAIL',
' WHERE LINKED_LOOKUP_ID = LOOKUPS_MNT.lookup_id_by_code (p_lookup_code => ''pricing_type'')',
'   AND NVL(IS_ACTIVE, 0) = 1',
' ORDER BY SEQ;'))
,p_begin_on_new_line=>'N'
,p_read_only_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_dependenceis NUMBER;',
'    l_gategory     NUMBER;',
'    l_pricing_type NUMBER;',
'BEGIN',
'    SELECT c005, c003',
'      INTO l_dependenceis, l_gategory',
'      FROM APEX_COLLECTIONS',
'     WHERE collection_name = ''AUCTION_DETAILS'';',
'    ',
'    FOR i IN (SELECT c005',
'                FROM APEX_COLLECTIONS',
'               WHERE collection_name = ''PRODUCT_DETAILS'') LOOP',
'        IF l_dependenceis <> LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''infath_product'', p_lookup_code => ''product_type'')',
'           OR l_gategory <> :P29_CATEGORY_PORTABLE OR i.c005 <> LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''meter_price'', p_lookup_code => ''pricing_type'') THEN',
'            RETURN TRUE;',
'        ELSE',
'            RETURN FALSE;',
'        END IF;',
'    END LOOP;',
'END;',
''))
,p_read_only_when2=>'PLSQL'
,p_read_only_when_type=>'FUNCTION_BODY'
,p_field_template=>wwv_flow_imp.id(148226641555951500)
,p_item_template_options=>'#DEFAULT#:t-Form-fieldContainer--stretchInputs:t-Form-fieldContainer--large:margin-top-md:t-Form-fieldContainer--radioButtonGroup'
