,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count NUMBER;',
'BEGIN',
'    ',
'    SELECT COUNT(ID) INTO v_count FROM EXTRA_EXPENSES_IN_TIMED_AUCTION WHERE PRODUCT_ID = :P29_PRODUCT_ID AND AUCTION_ID = :P29_AUCTION_ID;',
'    IF  v_count > 0 THEN ',
'        DELETE FROM EXTRA_EXPENSES_IN_TIMED_AUCTION ;',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20001, ''server error'');',
'        END IF; ',
'    END IF; ',
'    ',
'    DELETE FROM PRODUCTS_TEMP WHERE PRODUCT_ID = :P29_PRODUCT_ID AND AUCTION_ID = :P29_AUCTION_ID;',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20002, ''server error'');',
'    END IF;',
'',
'    UPDATE PRODUCTS',
'       SET STATUS = LOOKUPS_MNT.lookup_detail_id_by_code( p_lookup_detail_code => ''available'',  p_lookup_code => ''product_status'')',
'     WHERE ID = :P29_PRODUCT_ID;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20003, ''server error'');',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(57552487143371948)
,p_process_when_type=>'NEVER'
,p_internal_uid=>41519469676436844
);
