 p_id=>wwv_flow_imp.id(352926616882084523)
,p_plug_name=>'Documents'
,p_parent_plug_id=>wwv_flow_imp.id(169575347835070927)
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--noBorder:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(148155955406951451)
,p_plug_display_sequence=>80
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT sd.ID,',
'       CASE',
'        WHEN sd.CR_URL IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS CR_URL_CLASS,',
'        sd.CR_URL,',
'       CASE',
'        WHEN s.AVATAR_URL IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS LOGO_URL_class,',
'        s.AVATAR_URL AS LOGO_URL,',
'       CASE',
'        WHEN sd.ADMIN_ID_URL IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS ADMIN_ID_URL_CLASS,',
'        sd.ADMIN_ID_URL,',
'       CASE',
'        WHEN sd.NATIONAL_ADDRESS_URL IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS NATIONAL_ADDRESS_URL_CLASS,',
'        sd.NATIONAL_ADDRESS_URL,',
'       CASE',
'        WHEN sd.TAX_URL IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS TAX_URL_CLASS,',
'        sd.TAX_URL,',
'       CASE',
'        WHEN sd.IBAN_URL IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS IBAN_URL_CLASS,',
'        sd.IBAN_URL,',
'       CASE',
'        WHEN sd.APPLICANT_AUTHORIZATION_URL IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS APPLICANT_AUTHORIZATION_URL_CLASS,',
'        sd.APPLICANT_AUTHORIZATION_URL,',
'       CASE',
'        WHEN sd.ADMIN_AUTHORIZATION_URL IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS ADMIN_AUTHORIZATION_URL_CLASS,',
'        sd.ADMIN_AUTHORIZATION_URL,',
'       CASE',
'        WHEN sd.PORTABLE_CONTRACT_URL IS NOT NULL THEN',
'            ''<span class="fa fa-file-o"aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS PORTABLE_CONTRACT_URL_CLASS,',
'        sd.PORTABLE_CONTRACT_URL,',
'       CASE',
'        WHEN sd.REAL_ESTATE_CONTRACT_URL IS NOT NULL THEN',
'            ''<span class="fa fa-file-o"aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS REAL_ESTATE_CONTRACT_URL_CLASS,',
'        sd.REAL_ESTATE_CONTRACT_URL,',
'       CASE',
'        WHEN sd.SELLER_PORTABLE_CONTRACT_URL IS NOT NULL THEN',
'            ''<span class="fa fa-file-o"aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS SELLER_PORTABLE_CONTRACT_URLL_CLASS,',
'        sd.SELLER_PORTABLE_CONTRACT_URL,',
'       CASE',
'        WHEN sd.SELLER_REAL_ESTATE_CONTRACT_URL IS NOT NULL THEN',
'            ''<span class="fa fa-file-o"aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS SELLER_REAL_ESTATE_CONTRACT_URL_CLASS,',
'        sd.SELLER_REAL_ESTATE_CONTRACT_URL',
'  FROM SELLERS s,',
'       SELLERS_REQUESTS_DETAILS sd--, ',
'    --    SELLERS_REQUESTS_CONTRACTS sc',
' WHERE s.ID = sd.SELLER_ID ',
'--    AND sd.SELLER_ID = sc.SELLER_ID (+)',
'   AND sd.SELLER_ID = :P33_ID;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P33_ID'
,p_plug_read_only_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
