wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(57551073563371934)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update seller info'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE ',
'    v_result SELLERS_REQ.function_result;',
'BEGIN',
'    v_result := SELLERS_REQ.UPDATE_SELLER_INFO (',
'                -- seller table',
'                p_seller_id        => :P33_ID,',
'                P_seller_type_id   => :P33_SELLER_TYPE_ID,',
'                p_trade_name_ar    => :P33_TRADE_NAME_AR,',
'                p_trade_name_en    => :P33_TRADE_NAME_EN,',
'                p_tax_no           => :P33_TAX_NUMBER,',
'                p_cr_no            => :P33_SELL_IDENTITY_NUMBER,',
'                p_country_id       => :P33_COUNTRY_ID,',
'                -- seller details requests table',
'                p_applicant_type   => :P33_APPLICANT_TYPE_ID,',
'                p_applicant_name   => :P33_APP_NAME,',
'                p_email            => :P33_APP_EMAIL,',
'                p_phone            => :P33_APP_PHONE_NUMBER,',
'                -- seller bank details',
'                p_bank_id          => :P33_BANK_ID,',
'                p_currency_id      => :P33_CURRENCY_ID,',
'                p_account_no       => :P33_ACCOUNT_NO,',
'                p_iban_no          => :P33_IBAN,',
'                p_account_name     => :P33_ACCOUNT_NAME,',
'                -- cities and categories',
'                p_cities           => :P33_CITY_ID,',
'                p_categories       => :P33_CATEGORY_ID,',
'                p_lang             => :P_LANG);',
'',
'    IF v_result.code <> 1 THEN',
'        RAISE_APPLICATION_ERROR(-20001, v_result.code || '' - '' || v_result.message);',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(133768455572250736)
,p_internal_uid=>41517928883436829
);
