,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT IS_DROWNED,',
'           DROWING_INFO,',
'           DROWING_FILE_URL,',
'           IS_BURNED,',
'           BURN_INFO,',
'           BURN_FILE_URL,',
'           IS_ACCIDENT,',
'           ACCIDENT_INFO,',
'           ACCIDENT_FILE_URL',
'      INTO :P35_IS_DROWNED,',
'           :P35_DROWING_INFO,',
'           :P35_DROWING_FILE_URL,',
'           :P35_IS_BURNED,',
'           :P35_BURN_INFO,',
'           :P35_BURN_FILE_URL,',
'           :P35_IS_ACCIDENT,',
'           :P35_ACCIDENT_INFO,',
'           :P35_ACCIDENT_FILE_URL',
'      FROM CAR_DETAILS',
'     WHERE PRODUCT_ID = :P35_PRODUCT_ID;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P35_IS_DROWNED := NULL;',
'        :P35_DROWING_INFO := NULL;',
'        :P35_DROWING_FILE_URL := NULL;',
'        :P35_IS_BURNED := NULL;',
'        :P35_BURN_INFO := NULL;',
'        :P35_BURN_FILE_URL := NULL;',
'        :P35_IS_ACCIDENT := NULL;',
'        :P35_ACCIDENT_INFO := NULL;',
'        :P35_ACCIDENT_FILE_URL := NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>44385641495145429
);
