wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(63613456141125519)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Edit auction details'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_result                              VARCHAR2(5000);',
'    l_message                             VARCHAR2(5000);',
'    l_insurance_deducted                  VARCHAR2(255);',
'    l_trsyah                              VARCHAR2(255);',
'    l_is_auto_generate_full_invoice       VARCHAR2(255);',
'    l_is_auto_generate_commission_invoice VARCHAR2(255);',
'    l_is_winning_price_has_vat            VARCHAR2(255);',
'    header                                json_object_t;',
'    insurance_methods                     json_array_t;',
'BEGIN',
'    header              := json_object_t();',
'    insurance_methods   := json_array_t();',
'',
'    IF :P36_INSURANCE_DEDUCTED = 1 THEN l_insurance_deducted := ''TRUE''; ELSE l_insurance_deducted := ''FALSE''; END IF;',
'    IF :P36_TRSYAH = 1 THEN l_trsyah := ''TRUE''; ELSE l_trsyah := ''FALSE''; END IF;',
'    IF :P36_IS_AUTO_GENERATE_FULL_INVOICE = 1 THEN l_is_auto_generate_full_invoice := ''TRUE''; ELSE l_is_auto_generate_full_invoice := ''FALSE''; END IF;',
'    IF :P36_IS_AUTO_GENERATE_COMMISSION_INVOICE = 1 THEN l_is_auto_generate_commission_invoice := ''TRUE''; ELSE l_is_auto_generate_commission_invoice := ''FALSE''; END IF;',
'    IF :P36_IS_WINNING_PRICE_HAS_VAT = 1 THEN l_is_winning_price_has_vat := ''TRUE''; ELSE l_is_winning_price_has_vat := ''FALSE''; END IF;',
'',
'    -- insurance_methods.append(UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P36_INSURANCE_METHOD)));',
'',
'    header.put(''category'',                      TRIM(:P36_CATEGORY_ID));',
'    header.put(''auctionHost'',                   TRIM(UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P36_DEPENDENT))));',
'    header.put(''insurance_deducted'',            TRIM(l_insurance_deducted));',
'    header.put(''autoAwarding'',                  TRIM(l_trsyah));',
'    header.put(''autoGenerateFullInvoice'',       TRIM(l_is_auto_generate_full_invoice));',
'    header.put(''autoGenerateCommissionInvoice'', TRIM(l_is_auto_generate_commission_invoice));',
'    header.put(''winningPriceHasVat'',            TRIM(l_is_winning_price_has_vat));',
'    header.put(''insuranceMethods'',              UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P36_INSURANCE_METHOD)));',
'    header.put(''commission'',                    TRIM(:P36_COMMISSION));',
'    header.put(''commissionType'',                TRIM(UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P36_COMMISSION_TYPE_ID))));',
'    header.put(''nameAr'',                        TRIM(:P36_NAME_AR));',
'    header.put(''imageUrl'',                      TRIM(:P36_LOGO_URL));',
'    header.put(''brochure'',                      TRIM(:P36_BROCHURE_URL));',
'    header.put(''videoUrl'',                      TRIM(:P36_VIDEO_URL));',
'    header.put(''termsAndConditionsAr'',          TRIM(:P36_TERMS_AR));',
'',
'    l_result := SYSTEM_INTEGRATION.edit_auction (',
'                        p_body     => header.to_clob(),',
'                        p_id       => :P36_AUCTION_ID,',
'                        p_message  => l_message',
'                    );',
'',
'    header              := json_object_t();',
'    insurance_methods   := json_array_t();',
'',
'    IF l_result <> ''1'' THEN',
'        RAISE_APPLICATION_ERROR(-20003, l_message);',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(62691675875838128)
,p_internal_uid=>47580311461190414
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(62729697333446244)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Get data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT jt.category, jt.name, jt.imageUrl, jt.brochure, jt.termsAndConditions, jt.commission,',
'       LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => lower(jt.commissionType), p_lookup_code => ''commission_type''),',
'       LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => lower(jt.auctionHost), p_lookup_code => ''auction_dependency''),',
'       DECODE(jt.autoAwarding, ''true'', 1, 0), DECODE(jt.autoGenerateFullInvoice, ''true'', 1, 0),',
'       DECODE(jt.autoGenerateCommissionInvoice, ''true'', 1, 0), DECODE(jt.winningPriceHasVat, ''true'', 1, 0),',
'       LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => lower(ArrayToStr(jt.insuranceMethods)), p_lookup_code => ''insurance_method'')',
'  INTO :P36_CATEGORY_ID, :P36_NAME_AR, :P36_LOGO_URL, :P36_BROCHURE_URL, :P36_TERMS_AR, :P36_COMMISSION, :P36_COMMISSION_TYPE_ID, :P36_DEPENDENT, :P36_TRSYAH,',
'       :P36_IS_AUTO_GENERATE_FULL_INVOICE, :P36_IS_AUTO_GENERATE_COMMISSION_INVOICE, :P36_IS_WINNING_PRICE_HAS_VAT, :P36_INSURANCE_METHOD',
'  FROM',
'  JSON_TABLE (:P36_JSON,',
'     ''$''',
'        COLUMNS (',
'            category,',
'            name,',
'            imageUrl,',
'            brochure,',
'            termsAndConditions,',
'            commission,',
'            commissionType,',
'            auctionHost,',
'            autoAwarding,',
'            autoGenerateFullInvoice,',
'            autoGenerateCommissionInvoice,',
'            winningPriceHasVat,',
'            insuranceMethods VARCHAR2(100) FORMAT JSON PATH ''$.insuranceMethods''',
'        )',
'  ) AS jt;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>46696552653511139
);
end;
/
