wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(63570423863350622)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create Collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count         NUMBER;',
'    v_product_id    NUMBER;',
'    v_product_name  VARCHAR2(255);',
'BEGIN',
'    IF :P37_INSURANCE IS NULL THEN',
'        RAISE_APPLICATION_ERROR (-20001, ''Missing Data - The Insuracne must have a value'');',
'    END IF;',
'',
'    IF APEX_APPLICATION.g_f01.count = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20002, ''Missing Data - You need to add products'');',
'    END IF;',
'',
'    FOR i IN 1..APEX_APPLICATION.g_f01.count LOOP',
'        SELECT ID, NAME_AR',
'          INTO v_product_id, v_product_name',
'          FROM PRODUCTS',
'         WHERE ID = APEX_APPLICATION.g_f01(i);',
'',
'        IF NOT APEX_COLLECTION.collection_exists(''ADD_AUCTION_IN_CONTAINER'') THEN',
'            APEX_COLLECTION.create_collection(''ADD_AUCTION_IN_CONTAINER'');',
'',
'            APEX_COLLECTION.add_member (',
'                p_collection_name => ''ADD_AUCTION_IN_CONTAINER'',',
'                p_c001 => :P_SELLER_ID,',
'                p_c002 => :P37_AUCTION_ID,',
'                p_c003 => v_product_id,',
'                p_c004 => v_product_name,',
'                p_c005 => :P37_INSURANCE,',
'                p_c006 => :P37_START_PRICE,',
'                p_c007 => :P37_ALLOW_SELL_PRICE,',
'                p_c008 => :P37_EVERY_CLICK,',
'                p_c009 => :P37_START_DATE,',
'                p_c010 => :P37_END_DATE,',
'                p_c011 => :P37_PRODUCT_TERMS_AR,',
'                p_c012 => :P37_BUY_NOW_PRICE',
'            );',
'        ELSE',
'            APEX_COLLECTION.add_member (',
'                p_collection_name => ''ADD_AUCTION_IN_CONTAINER'',',
'                p_c001 => :P_SELLER_ID,',
'                p_c002 => :P37_AUCTION_ID,',
'                p_c003 => v_product_id,',
'                p_c004 => v_product_name,',
'                p_c005 => :P37_INSURANCE,',
'                p_c006 => :P37_START_PRICE,',
'                p_c007 => :P37_ALLOW_SELL_PRICE,',
'                p_c008 => :P37_EVERY_CLICK,',
'                p_c009 => :P37_START_DATE,',
'                p_c010 => :P37_END_DATE,',
'                p_c011 => :P37_PRODUCT_TERMS_AR,',
'                p_c012 => :P37_BUY_NOW_PRICE',
'            );',
'        END IF;',
'',
'        UPDATE PRODUCTS',
'           SET STATUS = LOOKUPS_MNT.lookup_detail_id_by_code( p_lookup_detail_code => ''on_auction'',  p_lookup_code => ''product_status'')',
'         WHERE ID = v_product_id;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20003, ''Product Status Updating Error'');',
'        END IF;',
'',
'        SELECT COUNT(SEQ_ID)',
'          INTO v_count',
'          FROM APEX_COLLECTIONS',
'         WHERE COLLECTION_NAME = ''ADD_AUCTION_EXTRA_EXPENSES'';',
'',
'        IF v_count > 0 THEN',
'            FOR i IN ( SELECT seq_id, c001, c002, c003 FROM APEX_COLLECTIONS WHERE COLLECTION_NAME = ''ADD_AUCTION_EXTRA_EXPENSES'' ORDER BY SEQ_ID ) LOOP',
'                IF NOT APEX_COLLECTION.collection_exists(''ADD_AUCTION_EXTRA_EXPENSES_IN_AUCTION'') THEN',
'                    APEX_COLLECTION.create_collection(''ADD_AUCTION_EXTRA_EXPENSES_IN_AUCTION'');',
'',
'                    APEX_COLLECTION.add_member (',
'                        p_collection_name => ''ADD_AUCTION_EXTRA_EXPENSES_IN_AUCTION'',',
'                        p_c001  => i.c001,',
'                        p_c002  => i.c002,',
'                        p_c003  => i.c003,',
'                        p_c004  => v_product_id',
'                    );',
'                ELSE',
'                    APEX_COLLECTION.add_member (',
'                        p_collection_name => ''ADD_AUCTION_EXTRA_EXPENSES_IN_AUCTION'',',
'                        p_c001  => i.c001,',
'                        p_c002  => i.c002,',
'                        p_c003  => i.c003,',
'                        p_c004  => v_product_id',
'                    );',
'                END IF;',
'            END LOOP;  ',
'        END IF;',
'    END LOOP;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(63566340517350613)
,p_internal_uid=>47537279183415517
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(67100111777960330)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Get Auctions IDs'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    :P37_PRODUCT_ID := null;',
'',
'    SELECT LISTAGG(jt.product, '','')',
'      INTO :P37_PRODUCT_ID',
'      FROM',
'      JSON_TABLE (:P37_JSON,',
'         ''$.auctions[*]''',
'            COLUMNS (',
'                product varchar2(500) path ''$.product''',
'            )',
'      ) AS jt;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when_type=>'NEVER'
,p_internal_uid=>51066967098025225
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(26322778454498033)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set Category ID'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DECODE(jt.category, ''ooo-ooo-ooo-ooo'', 2, jt.category) AS CATEGORY_ID',
'  INTO :P37_CATEGORY_ID',
'  FROM',
'  JSON_TABLE (:P37_JSON,',
'     ''$''',
'        COLUMNS (',
'            category',
'        )',
'  ) AS jt;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>10289633774562928
);
end;
