wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(63107078878151922)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Send auction products '
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_seller_name_ar     VARCHAR2(255);',
'    v_seller_name_en     VARCHAR2(255);',
'    v_seller_logo_url    VARCHAR2(2000);',
'    l_result             VARCHAR2(5000);',
'    l_message            VARCHAR2(5000);',
'    header               json_object_t;',
'    products_object      json_object_t;',
'    expenses_object      json_object_t;',
'    product_array        json_array_t;',
'    expenses_array       json_array_t;',
'BEGIN',
'    header          := json_object_t();',
'    products_object := json_object_t();',
'    expenses_object := json_object_t();',
'    product_array   := json_array_t();',
'    expenses_array  := json_array_t();',
'',
'    FOR i IN (SELECT c002 AS AUCTION_ID, c003 AS PRODUCT_ID, c004 AS PRODUCT_NAME, c005 AS INSURANCE, c006 AS START_PRICE, c007 AS ALLOW_SELL_PRICE,',
'                     c008 AS EVERY_CLICK, c009 AS START_DATE, c010 AS END_DATE, c011 AS PRODUCT_TERMS_AR, c012 AS BUY_NOW_PRICE',
'                FROM APEX_COLLECTIONS',
'               WHERE collection_name = ''ADD_AUCTION_IN_CONTAINER''',
'                 AND c001 = :P_SELLER_ID',
'                 AND c002 = :P38_AUCTION_ID)',
'    LOOP',
'        FOR j IN (SELECT c001 AS NAME_AR, c002 AS VALUE, UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => c003)) AS TYPE_ID',
'                    FROM APEX_COLLECTIONS',
'                   WHERE collection_name = ''ADD_AUCTION_EXTRA_EXPENSES_IN_AUCTION''',
'                     AND c004 = i.PRODUCT_ID )',
'        LOOP',
'            expenses_object.put(''nameAr'', TRIM(j.NAME_AR));',
'            expenses_object.put(''amount'', TRIM(j.VALUE));',
'            expenses_object.put(''type'',   TRIM(j.TYPE_ID));',
'',
'            expenses_array.append(expenses_object); ',
'            expenses_object := json_object_t();        ',
'        END LOOP;',
'            products_object.put(''product'',                  TO_CHAR(TRIM(i.PRODUCT_ID)));',
'            products_object.put(''nameAr'',                   ''product name'');',
'            -- products_object.put(''pricingType'',              TRIM(i.IS_METER_OR_PRICE));',
'            products_object.put(''insurance'',                TRIM(i.INSURANCE));',
'            products_object.put(''auctionOpeningPrice'',      TRIM(i.START_PRICE));',
'            products_object.put(''mimimumBid'',               TRIM(i.EVERY_CLICK));',
'            products_object.put(''minimumAcceptablePrice'',   TRIM(i.ALLOW_SELL_PRICE));',
'            products_object.put(''buyNowPrice'',              TRIM(i.BUY_NOW_PRICE));',
'            products_object.put(''termsAndConditionsAr'',     TRIM(i.PRODUCT_TERMS_AR));',
'            products_object.put(''startDateAndTime'',         TRIM(SYSTEM_CONTROLS.date_to_unix ( p_date => i.START_DATE)));',
'            products_object.put(''closingDateAndTime'',       TRIM(SYSTEM_CONTROLS.date_to_unix ( p_date => i.END_DATE)));',
'            -- products_object.put(''sequence'',                 TRIM(i.LANE_NO));',
'            products_object.put(''extraExpenses'',            expenses_array);',
'',
'            product_array.append(products_object); ',
'            products_object := json_object_t();',
'            expenses_array  := json_array_t();',
'    END LOOP;',
'',
'    -- header.put(''auctions'', product_array);',
'    -- RAISE_APPLICATION_ERROR(-20007, product_array.to_clob());',
'',
'    l_result := SYSTEM_INTEGRATION.send_auction_products (',
'                        p_body       => product_array.to_clob(),',
'                        p_auction_id => :P38_AUCTION_ID,',
'                        p_seller_id  => :P_SELLER_ID,',
'                        p_message    => l_message',
'                    );',
'',
'    products_object := json_object_t();',
'    expenses_object := json_object_t();',
'    product_array   := json_array_t();',
'    expenses_array  := json_array_t();',
'',
'    IF l_result <> ''1'' THEN',
'        RAISE_APPLICATION_ERROR(-20003, l_message);',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>47073934198216817
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(63587445568367073)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Clear temps'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF APEX_COLLECTION.collection_exists(''ADD_AUCTION_IN_CONTAINER'') THEN',
'        APEX_COLLECTION.truncate_collection ( p_collection_name => ''ADD_AUCTION_IN_CONTAINER'' );',
'    END IF;',
'',
'    IF APEX_COLLECTION.collection_exists(''ADD_AUCTION_EXTRA_EXPENSES'') THEN',
'        APEX_COLLECTION.truncate_collection ( p_collection_name => ''ADD_AUCTION_EXTRA_EXPENSES'' );',
'    END IF;',
'',
'    IF APEX_COLLECTION.collection_exists(''ADD_AUCTION_EXTRA_EXPENSES_IN_AUCTION'') THEN',
'        APEX_COLLECTION.truncate_collection ( p_collection_name => ''ADD_AUCTION_EXTRA_EXPENSES_IN_AUCTION'' );',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>47554300888431968
);
