wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(158314652987553502)
,p_name=>'Auction Information'
,p_template=>wwv_flow_imp.id(148155955406951451)
,p_display_sequence=>110
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-AVPList--variableLabelMedium:t-AVPList--leftAligned'
,p_grid_column_span=>6
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DECODE(jt.category, ''ooo-ooo-ooo-ooo'', 2, jt.category) AS CATEGORY_ID,',
'       jt.name AS NAME_AR,',
'       LOOKUPS_MNT.lookup_detail_name_by_code (p_lookup_detail_code => lower(jt.type), p_lookup_code => ''auction_type'', p_lang => ''ar'') AS AUCTION_TYPE_ID,',
'       TO_DATE(SUBSTR(jt.startDateAndTime, 1, INSTR(jt.startDateAndTime, ''T'') - 1), ''yyyy-mm-dd hh:mi'') AS START_DATE,',
'       TO_DATE(SUBSTR(jt.closingDateAndTime, 1, INSTR(jt.closingDateAndTime, ''T'') - 1), ''yyyy-mm-dd hh:mi'') AS END_DATE,',
unistr('       jt.auctionTotalDays || '' ( \064A\0648\0645 )'' AS DURATION,'),
'       jt.auctionsCount AS PRODUCTS_COUNT,',
'       ''<img src="''|| jt.imageUrl ||''" alt="Auction Logo" class="auction-image" style="width:30px;height:30px;" />'' AS LOGO_URL,',
'       jt.videoUrl AS VIDEO_URL,',
'       jt.brochure AS BROCHURE_URL,',
'       jt.termsAndConditions AS TERMS_AR',
'  FROM',
'  JSON_TABLE (:P39_JSON,',
'     ''$''',
'        COLUMNS (',
'            category,',
'            name,',
'            type,',
'            startDateAndTime,',
'            closingDateAndTime,',
'            auctionsCount,',
'            imageUrl,',
'            videoUrl,',
'            brochure,',
'            termsAndConditions,',
'            auctionTotalDays',
'        )',
'  ) AS jt'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(148185806889951470)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
