,p_event_id=>wwv_flow_imp.id(25166277964134189)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_name=>'Add Member'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF NOT APEX_COLLECTION.collection_exists(''AUCTION_EXTRA_EXPENSES'') THEN',
'        APEX_COLLECTION.create_collection(''AUCTION_EXTRA_EXPENSES'');',
'        APEX_COLLECTION.add_member (',
'            p_collection_name => ''AUCTION_EXTRA_EXPENSES'',',
'            p_c001 => :P40_NAME,',
'            p_c002 => :P40_VALUE,',
'            p_c003 => :P40_TYPE',
'        );',
'    ELSE',
'        APEX_COLLECTION.add_member (',
'            p_collection_name => ''AUCTION_EXTRA_EXPENSES'',',
'            p_c001 => :P40_NAME,',
'            p_c002 => :P40_VALUE,',
'            p_c003 => :P40_TYPE',
'        );',
