wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(25161464590134182)
,p_process_sequence=>60
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update product details API'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_result             VARCHAR2(5000);',
'    l_message            VARCHAR2(5000);',
'    auctions             json_object_t;',
'    expenses_object      json_object_t;',
'    expenses_array       json_array_t;',
'BEGIN',
'    auctions        := json_object_t();',
'    expenses_object := json_object_t();',
'    expenses_array  := json_array_t();',
'',
'    FOR i IN (SELECT c001 AS NAME, c002 AS AMOUNT, UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => c003)) AS TYPE',
'                FROM APEX_COLLECTIONS',
'               WHERE COLLECTION_NAME = ''AUCTION_EXTRA_EXPENSES'')',
'    LOOP',
'        expenses_object.put(''nameAr'', TRIM(i.NAME));',
'        expenses_object.put(''amount'', TRIM(i.AMOUNT));',
'        expenses_object.put(''type'',   TRIM(i.TYPE));',
'',
'        expenses_array.append(expenses_object);',
'        expenses_object := json_object_t();',
'    END LOOP; --EXTRA',
'',
'    auctions.put(''product'',                  TRIM(:P40_DB_PRODUCT_ID));',
'    auctions.put(''nameAr'',                   ''Product Name'');',
'    auctions.put(''insurance'',                TRIM(:P40_INSURANCE));',
'    auctions.put(''auctionOpeningPrice'',      TRIM(:P40_START_PRICE));',
'    auctions.put(''mimimumBid'',               TRIM(:P40_EVERY_CLICK));',
'    auctions.put(''minimumAcceptablePrice'',   TRIM(:P40_ALLOW_SELL_PRICE));',
'    auctions.put(''buyNowPrice'',              TRIM(:P40_BUY_NOW_PRICE));',
'    auctions.put(''termsAndConditionsAr'',     TRIM(:P40_TERMS_AND_CONDITIONS));',
'    auctions.put(''startDateAndTime'',         TRIM(SYSTEM_CONTROLS.date_to_unix ( p_date => :P40_START_DATE)));',
'    auctions.put(''closingDateAndTime'',       TRIM(SYSTEM_CONTROLS.date_to_unix ( p_date => :P40_END_DATE)));',
'    auctions.put(''extraExpenses'',            expenses_array);',
'',
'    l_result := SYSTEM_INTEGRATION.edit_auction_products (',
'                        p_body          => auctions.to_clob(),',
'                        p_auction_id    => :P40_PRODUCT_ID,',
'                        p_seller_id     => :P_SELLER_ID,',
'                        p_message       => l_message',
'                    );',
'',
'    expenses_object := json_object_t();',
'    expenses_array  := json_array_t();',
'',
'    IF l_result <> ''1'' THEN',
'        RAISE_APPLICATION_ERROR(-20003, l_message);',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(25148131852134158)
,p_internal_uid=>9128319910199077
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(25162307657134183)
,p_process_sequence=>90
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Send delete request to admin'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_name      VARCHAR2(255);',
'    v_image_url VARCHAR2(1000);',
'BEGIN',
'    SELECT NAME_AR, MAIN_IMAGE_URL',
'      INTO v_name, v_image_url',
'      FROM PRODUCTS',
'       WHERE ID = :P40_DB_PRODUCT_ID;',
'',
'    INSERT INTO AUCTION_DELETE_REQUESTS (',
'        SELLER_ID, USER_ID, AUCTION_ID, AUCTION_NAME, IMAGE_URL, BIDS, PARTICIPANTS, AUCTIONS_COUNT, STATUS, TYPE',
'    ) VALUES (',
'        :P_SELLER_ID, :P_USER_ID, :P40_PRODUCT_ID, v_name, v_image_url, 25, 11, 5,',
'        LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''pending'', p_lookup_code => ''request_status''),',
'        LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''auction'', p_lookup_code => ''auction_delete_type'')',
'    );',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20007, ''Insertion Error'');',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(25147277333134158)
,p_process_success_message=>'<h3 style="color:#026E63;">The request has been submitted successfully</h3>'
,p_internal_uid=>9129162977199078
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(25158289978134179)
,p_process_sequence=>50
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Get data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT jt.termsAndConditions, to_date(replace(replace(jt.startDateAndTime, ''T'', '' ''), ''.000Z'', '' ''), ''YYYY-MM-DD HH24:MI:SS''),',
'       to_date(replace(replace(jt.closingDateAndTime, ''T'', '' ''), ''.000Z'', '' ''), ''YYYY-MM-DD HH24:MI:SS''), jt.insurance, jt.auctionOpeningPrice, jt.mimimumBid, jt.minimumAcceptablePrice, jt.buyNowPrice, jt.product',
'  INTO :P40_TERMS_AND_CONDITIONS, :P40_START_DATE, :P40_END_DATE, :P40_INSURANCE, :P40_START_PRICE, :P40_EVERY_CLICK, :P40_ALLOW_SELL_PRICE, :P40_BUY_NOW_PRICE, :P40_DB_PRODUCT_ID',
'  FROM',
'  JSON_TABLE (:P40_JSON,',
'     ''$.auctions[*]''',
'        COLUMNS (',
'            id                  varchar2(500) path ''$._id'',',
'            termsAndConditions  varchar2(500) path ''$.termsAndConditions'',',
'            status              varchar2(500) path ''$.status'',',
'            startDateAndTime    varchar2(500) path ''$.startDateAndTime'',',
'            closingDateAndTime  varchar2(500) path ''$.closingDateAndTime'',',
'            insurance           varchar2(500) path ''$.insurance'',',
'            auctionOpeningPrice varchar2(500) path ''$.auctionOpeningPrice'',',
'            mimimumBid          varchar2(500) path ''$.mimimumBid'',',
'            minimumAcceptablePrice varchar2(500) path ''$.minimumAcceptablePrice'',',
'            buyNowPrice         varchar2(500) path ''$.buyNowPrice'',',
'            product             varchar2(500) path ''$.product''',
'        )',
'  ) AS jt',
' WHERE jt.id = :P40_PRODUCT_ID;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>9125145298199074
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(25375653732214706)
,p_process_sequence=>60
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF APEX_COLLECTION.collection_exists(''AUCTION_EXTRA_EXPENSES'') THEN',
'        APEX_COLLECTION.truncate_collection (p_collection_name => ''AUCTION_EXTRA_EXPENSES'');',
'    END IF;',
'',
'    FOR i IN (',
'        SELECT jt.id, jt.name AS name, jt.amount AS amount,LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => lower(jt.type), p_lookup_code => ''commission_type'') AS type',
'          FROM',
'          JSON_TABLE (:P40_JSON,',
'             ''$.auctions[*]''',
'                COLUMNS (',
'                    id          varchar2(500) path ''$._id'',',
'                    NESTED PATH ''$.extraExpenses[*]''  COLUMNS (',
'                        name    varchar2(500) path ''$.name'',',
'                        amount  varchar2(500) path ''$.amount'',',
'                        type    varchar2(500) path ''$.type''',
'                    )',
'                )',
'          ) AS jt',
'         WHERE jt.id = :P40_PRODUCT_ID',
'    ) LOOP',
'        IF NOT APEX_COLLECTION.collection_exists(''AUCTION_EXTRA_EXPENSES'') THEN',
'           APEX_COLLECTION.create_collection(''AUCTION_EXTRA_EXPENSES'');',
'           APEX_COLLECTION.add_member (',
'               p_collection_name => ''AUCTION_EXTRA_EXPENSES'',',
'               p_c001 => i.name,',
'               p_c002 => i.amount,',
'               p_c003 => i.type',
'           );',
'        ELSE',
'            APEX_COLLECTION.add_member (',
'                p_collection_name => ''AUCTION_EXTRA_EXPENSES'',',
'                p_c001 => i.name,',
'                p_c002 => i.amount,',
'                p_c003 => i.type',
'            );',
'        END IF;',
'    END LOOP;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>9342509052279601
);
end;
/
