wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(26414421610234709)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update Collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P41_INSURANCE IS NULL THEN',
'        RAISE_APPLICATION_ERROR (-20001, ''Missing Data - The Insuracne must have a value'');',
'    END IF;',
'',
'    APEX_COLLECTION.update_member (',
'        p_collection_name => ''ADD_AUCTION_IN_CONTAINER'',',
'        p_seq  => :P41_SEQUENCE,',
'        P_c001 => :P_SELLER_ID,',
'        P_c002 => :P41_AUCTION_ID,',
'        P_c003 => :P41_PRODUCT_ID,',
'        P_c004 => :P41_PRODUCT_NAME,',
'        p_c005 => :P41_INSURANCE,',
'        p_c006 => :P41_START_PRICE,',
'        p_c007 => :P41_ALLOW_SELL_PRICE,',
'        p_c008 => :P41_EVERY_CLICK,',
'        p_c009 => :P41_START_DATE,',
'        p_c010 => :P41_END_DATE,',
'        p_c011 => :P41_PRODUCT_TERMS_AR',
'    );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(26407725755234701)
,p_internal_uid=>10381276930299604
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(26322515687498030)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Delete Auction'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF APEX_COLLECTION.collection_exists(''ADD_AUCTION_IN_CONTAINER'') THEN',
'        APEX_COLLECTION.DELETE_MEMBER (',
'            p_collection_name => ''ADD_AUCTION_IN_CONTAINER'',',
'            p_seq => :P41_SEQUENCE',
'        );',
'    END IF;',
'',
'    IF APEX_COLLECTION.collection_exists(''ADD_AUCTION_EXTRA_EXPENSES_IN_AUCTION'') THEN',
'        FOR i IN (',
'            SELECT SEQ_ID AS ID',
'              FROM APEX_COLLECTIONS',
'             WHERE COLLECTION_NAME = ''ADD_AUCTION_EXTRA_EXPENSES_IN_AUCTION''',
'               AND c004 = :P41_PRODUCT_ID )',
'        LOOP',
'            APEX_COLLECTION.DELETE_MEMBER (',
'                p_collection_name => ''ADD_AUCTION_EXTRA_EXPENSES_IN_AUCTION'',',
'                p_seq => i.ID',
'            );',
'        END LOOP;',
'    END IF;',
'',
'    UPDATE PRODUCTS',
'       SET STATUS = LOOKUPS_MNT.lookup_detail_id_by_code( p_lookup_detail_code => ''available'',  p_lookup_code => ''product_status'')',
'     WHERE ID = :P41_PRODUCT_ID;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(26322138063498026)
,p_process_success_message=>'The product has been successfully deleted'
,p_internal_uid=>10289371007562925
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(26321918744498024)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_CLOSE_WINDOW'
,p_process_name=>'Close Dialog'
,p_attribute_02=>'Y'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>10288774064562919
