wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(26414839084234710)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Get data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF APEX_COLLECTION.collection_exists(''ADD_AUCTION_IN_CONTAINER'') THEN',
'        SELECT c005 AS INSURANCE,',
'               c006 AS START_PRICE,',
'               c007 AS ALLOW_SELL_PRICE,',
'               c008 AS EVERY_CLICK,',
'               c009 AS START_DATE,',
'               c010 AS END_DATE,',
'               c011 AS PRODUCT_TERMS_AR',
'          INTO :P41_INSURANCE,',
'               :P41_START_PRICE,',
'               :P41_ALLOW_SELL_PRICE,',
'               :P41_EVERY_CLICK,',
'               :P41_START_DATE,',
'               :P41_END_DATE,',
'               :P41_PRODUCT_TERMS_AR',
'          FROM APEX_COLLECTIONS',
'         WHERE COLLECTION_NAME = ''ADD_AUCTION_IN_CONTAINER''',
'           AND seq_id = :P41_SEQUENCE;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>10381694404299605
);
end;
